  ('dumbbell_rdl', 'Rumunský Mrtvý Tah s jednoručkami', 'Nohy', '{"Hamstringy","Hýždě"}', 'S jednoručkami u stehen se předklánějte v kyčlích a plynulým tahem hýždí a hamstringů se vracejte nahoru.', 'https://raw.githubusercontent.com/hasaneyldrm/exercises-dataset/main/videos/0387-gH5fRsC.gif', TRUE, 'weight_reps'),
  ('hip_thrust_barbell', 'Hip Thrust s Velkou Činkou na lavičce', 'Nohy', '{"Hýždě","Hamstringy"}', 'Lopatky opřené o lavičku, osa na bocích. Vytlačujte pánev nahoru do plného propnutí a zatnutí hýždí.', 'https://raw.githubusercontent.com/hasaneyldrm/exercises-dataset/main/videos/0500-11wrviz.gif', TRUE, 'weight_reps'),
  ('glute_bridge', 'Zvedání pánve na zemi (Glute Bridge)', 'Nohy', '{"Hýždě","Hamstringy"}', 'Lehněte si na záda s pokrčenými koleny a zvedejte pánev nahoru se silným stiskem hýždí.', 'https://raw.githubusercontent.com/hasaneyldrm/exercises-dataset/main/videos/0473-nuBF9MO.gif', TRUE, 'reps_only'),
  ('walking_lunges', 'Výpady v chůzi s jednoručkami', 'Nohy', '{"Hýždě","Kvadricepsy","Hamstringy"}', 'Dělejte dlouhé kroky dopředu, zadní koleno těsně nad zem. Plynulý krok a rovný trup.', 'https://raw.githubusercontent.com/hasaneyldrm/exercises-dataset/main/videos/0337-L2V5Nan.gif', TRUE, 'weight_reps'),
  ('reverse_lunges', 'Výpady vzad s Velkou Činkou', 'Nohy', '{"Hýždě","Kvadricepsy"}', 'Z výchozího stoje ukročte jednou nohou vzad a klesejte kolenem k zemi. Šetrnější ke kolenům.', 'https://raw.githubusercontent.com/hasaneyldrm/exercises-dataset/main/videos/0078-VaP75jl.gif', TRUE, 'weight_reps'),
  ('standing_calf_raise', 'Výpony na lýtka ve stoje (Standing Calf Raise)', 'Nohy', '{"Dvojhlavý sval lýtkový (Gastrocnemius)"}', 'Z plného protažení paty dolů se zvedněte na špičky a podržte vrcholnou kontrakci na 1 sekundu.', 'https://raw.githubusercontent.com/hasaneyldrm/exercises-dataset/main/videos/1372-8ozhUIZ.gif', TRUE, 'weight_reps'),
  ('seated_calf_raise', 'Výpony na lýtka v sedě (Seated Calf Raise)', 'Nohy', '{"Šikmý sval lýtkový (Soleus)"}', 'V sedě na stroji zvedejte špičky s důrazem na hloubku lýtka a plný rozsah pohybu.', 'https://raw.githubusercontent.com/hasaneyldrm/exercises-dataset/main/videos/0088-ktsFQAZ.gif', TRUE, 'weight_reps'),
  ('abductor_machine', 'Roznožování na stroji v sedě (Abdukce)', 'Nohy', '{"Střední hýžďový sval"}', 'V sedě tlačte kolena od sebe do stran s krátkou výdrží v maximálním roznožení.', 'https://raw.githubusercontent.com/hasaneyldrm/exercises-dataset/main/videos/0597-CHpahtl.gif', TRUE, 'weight_reps'),
  ('adductor_machine', 'Snožování na stroji v sedě (Addukce)', 'Nohy', '{"Přitahovače stehen (Vnitřní stehna)"}', 'Tlačte kolena plynule k sobě a zatněte vnitřní stranu stehen.', 'https://raw.githubusercontent.com/hasaneyldrm/exercises-dataset/main/videos/0598-oHsrypV.gif', TRUE, 'weight_reps'),
  ('step_ups', 'Vystupování na lavičku / bednu s JČ (Step-ups)', 'Nohy', '{"Hýždě","Kvadricepsy","Lýtka"}', 'Střídavě vystupujte celým chodidlem na lavičku a zvedejte tělo silou přední nohy.', 'https://raw.githubusercontent.com/hasaneyldrm/exercises-dataset/main/videos/0415-SxHteRW.gif', TRUE, 'weight_reps'),
