  ('ez_bar_curl', 'Bicepsový zdvih s EZ osou', 'Ruce', '{"Biceps","Předloktí"}', 'EZ osa šetří zápěstí a lokty. Fixujte lokty u těla a táhněte činku silou bicepsů.', 'https://raw.githubusercontent.com/hasaneyldrm/exercises-dataset/main/videos/0447-6TG6x2w.gif', TRUE, 'weight_reps'),
  ('dumbbell_curl', 'Bicepsový zdvih s JČ se supinací', 'Ruce', '{"Biceps","Předloktí"}', 'Při zvedání vytáčejte malíček nahoru (supinace) pro maximální vrchol kontrakce bicepsu.', 'https://raw.githubusercontent.com/hasaneyldrm/exercises-dataset/main/videos/0294-NbVPDMW.gif', TRUE, 'weight_reps'),
