  ('incline_dumbbell_curl', 'Bicepsový zdvih na šikmé lavici s JČ', 'Ruce', '{"Dlouhá hlava bicepsu"}', 'Na lavici s úhlem 45° nechte paže viset kolmo dolů pro extrémní protažení dlouhé hlavy bicepsu.', 'https://raw.githubusercontent.com/hasaneyldrm/exercises-dataset/main/videos/0316-B3Rxp6L.gif', TRUE, 'weight_reps'),
  ('preacher_curl', 'Scottova lavice s EZ osou (Preacher Curl)', 'Ruce', '{"Krátká hlava bicepsu"}', 'Opřete nadloktí o šikmou opěrku a eliminujte jakýkoliv souhyb těla pro čistou izolaci bicepsu.', 'https://raw.githubusercontent.com/hasaneyldrm/exercises-dataset/main/videos/0448-DgZQ11d.gif', TRUE, 'weight_reps'),
