  ('cable_high_biceps_curl', 'Biceps na horních protisměrných kladkách', 'Ruce', '{"Biceps"}', 'Stůjte uprostřed s rozpaženými pažemi a přitahujte madla k uším do vrcholné kontrakce.', 'https://raw.githubusercontent.com/hasaneyldrm/exercises-dataset/main/videos/0182-61GrD55.gif', TRUE, 'weight_reps'),
  ('reverse_barbell_curl', 'Bicepsový zdvih nadhmatem s VČ', 'Ruce', '{"Vřetenní sval (Brachioradialis)","Předloktí"}', 'Úchop nadhmatem. Extrémně účinný cvik na horní stranu předloktí a sílu úchopu.', 'https://raw.githubusercontent.com/hasaneyldrm/exercises-dataset/main/videos/0080-xNrS20v.gif', TRUE, 'weight_reps'),
  ('tricep_rope_pushdown', 'Stahování kladky na triceps s lanem', 'Ruce', '{"Vnější hlava tricepsu"}', 'Lokty u těla. V dolní fázi roztáhněte konce lana od sebe a propněte paže.', 'https://raw.githubusercontent.com/hasaneyldrm/exercises-dataset/main/videos/0241-gAwDzB3.gif', TRUE, 'weight_reps'),
  ('tricep_bar_pushdown', 'Stahování kladky s rovnou / V-tyčí', 'Ruce', '{"Triceps"}', 'Tlačte tyč přímo dolů do plného uzamčení loktů a na vteřinu zatněte triceps.', 'https://raw.githubusercontent.com/hasaneyldrm/exercises-dataset/main/videos/0200-dU605di.gif', TRUE, 'weight_reps'),
