  ('high_knees', 'Běh na místě s vysokými koleny (High Knees)', 'Kardio', '{"Ohybače kyčlí","Lýtka","Břicho"}', 'Běhejte na špičkách a zvedejte kolena do výšky pasu s energickým souhybem paží.', 'https://raw.githubusercontent.com/hasaneyldrm/exercises-dataset/main/videos/0537-vzAxBtt.gif', TRUE, 'duration'),
  ('treadmill_running', 'Běh na běžeckém pásu', 'Kardio', '{"Nohy","Kardiovaskulární systém"}', 'Plynulý běžecký krok, vzpřímený trup a pravidelné dýchání na zvolenou rychlost a sklon.', 'https://raw.githubusercontent.com/hasaneyldrm/exercises-dataset/main/videos/0814-X6C6i5Y.gif', TRUE, 'distance_duration'),
  ('stationary_bike', 'Jízda na rotopedu / Airbike', 'Kardio', '{"Kvadricepsy","Kardio"}', 'Šlapání s nastaveným odporem pro šetrné a účinné kardio bez nárazů na klouby.', 'https://raw.githubusercontent.com/hasaneyldrm/exercises-dataset/main/videos/2138-H1PESYI.gif', TRUE, 'distance_duration'),
  ('air_bike_sprint', 'Air Bike / Assault Bike sprinty', 'Kardio', '{"Celé tělo","Kvadricepsy","Kardio"}', 'Zapojte současně nohy i paže pro maximální kalorický výdej a anaerobní kapacitu.', 'https://raw.githubusercontent.com/hasaneyldrm/exercises-dataset/main/videos/0003-1ZFqTDN.gif', TRUE, 'duration'),
  ('battle_ropes', 'Vlnění s bojovými lany (Battle Ropes)', 'Kardio', '{"Ramena","Ruce","Střed těla"}', 'V mírném podřepu střídavě či současně vytvářejte vlnění lany s maximální intenzitou.', 'https://raw.githubusercontent.com/hasaneyldrm/exercises-dataset/main/videos/0128-RJa4tCo.gif', TRUE, 'duration'),
  ('ex_archer_push_up', 'Lukostřelecké kliky (Archer Push-up)', 'Hrudník', '{"Triceps","Ramena","Střed těla"}', 'Start in a push-up position with your hands slightly wider than shoulder-width apart. Extend one arm straight out to the side, parallel to the ground. Lower your body by bending your elbows, keeping your back straight and core engaged.', 'https://raw.githubusercontent.com/hasaneyldrm/exercises-dataset/main/videos/3294-A9qxk2F.gif', TRUE, 'reps_only'),
  ('ex_assisted_chest_dip_kneeling', 'Assisted chest Kliky na bradlech (v kleče)', 'Hrudník', '{"Triceps","Ramena"}', 'Adjust the machine to your desired height and secure your knees on the pad. Grasp the handles with your palms facing down and your arms fully extended. Lower your body by bending your elbows until your upper arms are parallel to the floor.', 'https://raw.githubusercontent.com/hasaneyldrm/exercises-dataset/main/videos/0009-PAgTVaK.gif', TRUE, 'weight_reps'),
  ('ex_assisted_wide_grip_chest_dip_kneeling', 'Assisted širokým úchopem chest Kliky na bradlech (v kleče)', 'Hrudník', '{"Triceps","Ramena"}', 'Adjust the machine to your desired height and secure your knees on the pad. Grasp the handles with a wide grip and keep your elbows slightly bent. Lower your body by bending your elbows until your upper arms are parallel to the floor.', 'https://raw.githubusercontent.com/hasaneyldrm/exercises-dataset/main/videos/2364-PnZJIrk.gif', TRUE, 'weight_reps'),
  ('ex_barbell_decline_pullover', 'S Velkou činkou (VČ) hlavou dolů Pullover', 'Hrudník', '{"Triceps","Ramena"}', 'Lie down on a decline bench with your head lower than your hips and your feet secured. Hold the barbell with a pronated grip (palms facing away from you) and your hands slightly wider than shoulder-width apart. Extend your arms above your chest, keeping a slight bend in your elbows.', 'https://raw.githubusercontent.com/hasaneyldrm/exercises-dataset/main/videos/1255-9sgNE2O.gif', TRUE, 'weight_reps'),
  ('ex_barbell_decline_wide_grip_press', 'S Velkou činkou (VČ) hlavou dolů širokým úchopem Tlaky', 'Hrudník', '{"Triceps","Ramena"}', 'Lie on a decline bench with your feet secured and your head lower than your hips. Grasp the barbell with a wide grip, slightly wider than shoulder-width apart. Lower the barbell to your chest, keeping your elbows out to the sides.', 'https://raw.githubusercontent.com/hasaneyldrm/exercises-dataset/main/videos/0036-hl8DUh8.gif', TRUE, 'weight_reps'),
  ('ex_barbell_front_raise_and_pullover', 'S Velkou činkou (VČ) Předpažování a Pullover', 'Hrudník', '{"Ramena","Triceps"}', 'Stand with your feet shoulder-width apart and hold a barbell with an overhand grip, palms facing down. Keep your arms straight and raise the barbell in front of you until it reaches shoulder height. Pause for a moment at the top, then slowly lower the barbell back down to the starting position.', 'https://raw.githubusercontent.com/hasaneyldrm/exercises-dataset/main/videos/0040-33AzZeV.gif', TRUE, 'weight_reps'),
  ('ex_barbell_guillotine_bench_press', 'Gilotinový bench press (k hrdlu)', 'Hrudník', '{"Ramena","Triceps"}', 'Lie flat on a bench with your feet flat on the ground and your back pressed against the bench. Grasp the barbell with an overhand grip, slightly wider than shoulder-width apart. Lower the barbell slowly towards your neck, keeping your elbows pointed outwards.', 'https://raw.githubusercontent.com/hasaneyldrm/exercises-dataset/main/videos/0045-GXoaSgn.gif', TRUE, 'weight_reps'),
  ('ex_barbell_reverse_grip_decline_bench_press', 'S Velkou činkou (VČ) podhmatem hlavou dolů Bench Press', 'Hrudník', '{"Triceps","Ramena"}', 'Lie on a decline bench with your feet secured and your head lower than your hips. Grasp the barbell with a reverse grip, slightly wider than shoulder-width apart. Unrack the barbell and lower it slowly towards your chest, keeping your elbows tucked in.', 'https://raw.githubusercontent.com/hasaneyldrm/exercises-dataset/main/videos/1256-DotAgEF.gif', TRUE, 'weight_reps'),
  ('ex_barbell_reverse_grip_incline_bench_press', 'S Velkou činkou (VČ) podhmatem šikmo nahoru Bench Press', 'Hrudník', '{"Triceps","Ramena"}', 'Set up an incline bench at a 45-degree angle. Lie down on the bench with your feet flat on the ground. Grasp the barbell with a reverse grip, hands slightly wider than shoulder-width apart.', 'https://raw.githubusercontent.com/hasaneyldrm/exercises-dataset/main/videos/1257-DU7I633.gif', TRUE, 'weight_reps'),
  ('ex_barbell_wide_bench_press', 'S Velkou činkou (VČ) širokým úchopem Bench Press', 'Hrudník', '{"Ramena","Triceps"}', 'Lie flat on a bench with your feet flat on the ground and your back pressed against the bench. Grasp the barbell with a wide grip, slightly wider than shoulder-width apart. Lift the barbell off the rack and hold it directly above your chest with your arms fully extended.', 'https://raw.githubusercontent.com/hasaneyldrm/exercises-dataset/main/videos/0122-JsKq9so.gif', TRUE, 'weight_reps'),
  ('ex_barbell_wide_reverse_grip_bench_press', 'S Velkou činkou (VČ) širokým úchopem podhmatem Bench Press', 'Hrudník', '{"Triceps","Ramena"}', 'Lie flat on a bench with your feet flat on the ground and your back pressed against the bench. Grasp the barbell with a wide reverse grip, slightly wider than shoulder-width apart. Lift the barbell off the rack and hold it directly above your chest with your arms fully extended.', 'https://raw.githubusercontent.com/hasaneyldrm/exercises-dataset/main/videos/1258-945zpRg.gif', TRUE, 'weight_reps'),
  ('ex_cable_bench_press', 'Na kladce Bench Press', 'Hrudník', '{"Triceps","Ramena"}', 'Adjust the cable machine to chest height and attach the handles. Stand facing away from the machine with your feet shoulder-width apart. Grasp the handles with an overhand grip and step forward to create tension in the cables.', 'https://raw.githubusercontent.com/hasaneyldrm/exercises-dataset/main/videos/0151-7xI5MXA.gif', TRUE, 'weight_reps'),
  ('ex_cable_cross_over_variation', 'Na kladce křížení kladek variace', 'Hrudník', '{"Ramena","Triceps"}', 'Adjust the cable pulleys to chest height. Stand in the center of the cable machine with one foot in front of the other. Grasp the handles with your palms facing down and your arms extended out to the sides.', 'https://raw.githubusercontent.com/hasaneyldrm/exercises-dataset/main/videos/0155-0CXGHya.gif', TRUE, 'weight_reps'),
  ('ex_cable_decline_fly', 'Na kladce hlavou dolů Rozpažování', 'Hrudník', '{"Ramena","Triceps"}', 'Adjust the cable machine to a decline position. Stand facing away from the machine with your feet shoulder-width apart. Hold the handles with your palms facing forward and your arms extended straight out in front of you.', 'https://raw.githubusercontent.com/hasaneyldrm/exercises-dataset/main/videos/0158-7saC5zz.gif', TRUE, 'weight_reps'),
  ('ex_cable_decline_one_arm_press', 'Na kladce hlavou dolů jednoruč Tlaky', 'Hrudník', '{"Triceps","Ramena"}', 'Adjust the cable machine to a decline position. Stand facing away from the machine and grab the handle with one hand. Position yourself with your back against the decline bench and your arm extended straight in front of you.', 'https://raw.githubusercontent.com/hasaneyldrm/exercises-dataset/main/videos/1260-KHGNa16.gif', TRUE, 'weight_reps'),
  ('ex_cable_decline_press', 'Na kladce hlavou dolů Tlaky', 'Hrudník', '{"Triceps","Ramena"}', 'Adjust the cable machine to a decline position. Sit on the decline bench facing the cable machine. Grasp the handles with an overhand grip and position them at chest level.', 'https://raw.githubusercontent.com/hasaneyldrm/exercises-dataset/main/videos/1261-2Pya1cP.gif', TRUE, 'weight_reps'),
  ('ex_cable_incline_bench_press', 'Na kladce šikmo nahoru Bench Press', 'Hrudník', '{"Ramena","Triceps"}', 'Adjust the bench to a 45-degree incline. Attach the cable handles to the high pulleys. Sit on the bench facing the cable machine with your feet flat on the ground.', 'https://raw.githubusercontent.com/hasaneyldrm/exercises-dataset/main/videos/0169-Vh0GsK4.gif', TRUE, 'weight_reps'),
  ('ex_cable_incline_fly', 'Na kladce šikmo nahoru Rozpažování', 'Hrudník', '{"Ramena","Triceps"}', 'Adjust the cable machine to a low position and attach the handles. Sit on an incline bench with your back against the pad and feet flat on the floor. Grasp the handles with an overhand grip and extend your arms straight out in front of you.', 'https://raw.githubusercontent.com/hasaneyldrm/exercises-dataset/main/videos/0171-tBWXbIT.gif', TRUE, 'weight_reps'),
  ('ex_cable_lying_fly', 'Na kladce v leže Rozpažování', 'Hrudník', '{"Ramena","Triceps"}', 'Attach the handles to the cables and lie flat on a bench with your feet flat on the ground. Hold the handles with your palms facing each other and your arms extended straight above your chest. Keeping a slight bend in your elbows, lower your arms out to the sides in a wide arc until you feel a stretch in your chest.', 'https://raw.githubusercontent.com/hasaneyldrm/exercises-dataset/main/videos/0185-lJJ7Yq8.gif', TRUE, 'weight_reps'),
  ('ex_cable_middle_fly', 'Na kladce na střední část Rozpažování', 'Hrudník', '{"Ramena","Triceps"}', 'Attach cables to both sides of a cable machine at chest height. Stand in the center of the machine with one foot slightly in front of the other. Grasp the handles with an overhand grip and extend your arms out to the sides.', 'https://raw.githubusercontent.com/hasaneyldrm/exercises-dataset/main/videos/0188-xLYSdtg.gif', TRUE, 'weight_reps'),
  ('ex_cable_one_arm_decline_chest_fly', 'Na kladce jednoruč hlavou dolů chest Rozpažování', 'Hrudník', '{"Ramena","Triceps"}', 'Attach a D-handle to a low pulley cable machine and set the bench to a decline angle. Lie down on the bench with your head towards the machine and grab the handle with your right hand. Extend your arm straight up above your chest, keeping a slight bend in your elbow.', 'https://raw.githubusercontent.com/hasaneyldrm/exercises-dataset/main/videos/1262-w4dLzSx.gif', TRUE, 'weight_reps'),
  ('ex_cable_one_arm_fly_on_exercise_ball', 'Na kladce jednoruč Rozpažování on exercise ball', 'Hrudník', '{"Ramena","Triceps"}', 'Sit on an exercise ball with your feet flat on the ground and your back straight. Hold a cable handle in one hand and extend your arm out to the side, parallel to the ground. Keep your elbow slightly bent and your palm facing forward.', 'https://raw.githubusercontent.com/hasaneyldrm/exercises-dataset/main/videos/1263-hHy8tQG.gif', TRUE, 'weight_reps'),
  ('ex_cable_one_arm_incline_fly_on_exercise_ball', 'Na kladce jednoruč šikmo nahoru Rozpažování on exercise ball', 'Hrudník', '{"Ramena","Triceps"}', 'Sit on an exercise ball with your feet flat on the ground and your back against an incline bench. Hold a cable handle in one hand with your arm extended and palm facing inward. Keeping a slight bend in your elbow, slowly lower your arm out to the side until your hand is in line with your shoulder.', 'https://raw.githubusercontent.com/hasaneyldrm/exercises-dataset/main/videos/1264-P14Dz9D.gif', TRUE, 'weight_reps'),
  ('ex_cable_one_arm_incline_press', 'Na kladce jednoruč šikmo nahoru Tlaky', 'Hrudník', '{"Ramena","Triceps"}', 'Adjust the cable machine to a low pulley position. Sit on an incline bench facing away from the cable machine. Grasp the handle with one hand and bring it up to shoulder height.', 'https://raw.githubusercontent.com/hasaneyldrm/exercises-dataset/main/videos/1265-GKEH6jj.gif', TRUE, 'weight_reps'),
  ('ex_cable_one_arm_incline_press_on_exercise_ball', 'Na kladce jednoruč šikmo nahoru Tlaky on exercise ball', 'Hrudník', '{"Ramena","Triceps"}', 'Sit on an exercise ball with your feet flat on the ground and your back resting against an incline bench. Hold a cable handle in one hand and position your arm at a 90-degree angle with your elbow bent. Press the cable handle forward and upward, extending your arm fully.', 'https://raw.githubusercontent.com/hasaneyldrm/exercises-dataset/main/videos/1266-6t00BsF.gif', TRUE, 'weight_reps'),
  ('ex_cable_one_arm_lateral_bent_over', 'Na kladce jednoruč lateral bent-over', 'Hrudník', '{"Ramena","trapezius"}', 'Stand with your feet shoulder-width apart, facing a cable machine. Grasp the handle with one hand and step back to create tension on the cable. Bend forward at the waist, keeping your back straight and your core engaged.', 'https://raw.githubusercontent.com/hasaneyldrm/exercises-dataset/main/videos/0191-dB07vDu.gif', TRUE, 'weight_reps'),
  ('ex_cable_one_arm_press_on_exercise_ball', 'Na kladce jednoruč Tlaky on exercise ball', 'Hrudník', '{"Ramena","Triceps"}', 'Sit on an exercise ball with your feet flat on the ground and your back straight. Hold a cable handle in one hand and position your arm at chest height, elbow bent. Place your other hand on your hip for stability.', 'https://raw.githubusercontent.com/hasaneyldrm/exercises-dataset/main/videos/1267-MKIelrR.gif', TRUE, 'weight_reps'),
  ('ex_cable_press_on_exercise_ball', 'Na kladce Tlaky on exercise ball', 'Hrudník', '{"Ramena","Triceps"}', 'Sit on an exercise ball with your feet flat on the ground and your knees at a 90-degree angle. Hold the cable handles at chest height with your palms facing down and your elbows bent. Engage your core and press the cable handles forward until your arms are fully extended.', 'https://raw.githubusercontent.com/hasaneyldrm/exercises-dataset/main/videos/1268-vAwm6rK.gif', TRUE, 'weight_reps'),
  ('ex_cable_seated_chest_press', 'Na kladce v sedě Tlaky na prsa', 'Hrudník', '{"Ramena","Triceps"}', 'Adjust the seat height and cable handles to a comfortable position. Sit on the bench with your back straight and feet flat on the floor. Grasp the cable handles with an overhand grip at shoulder height.', 'https://raw.githubusercontent.com/hasaneyldrm/exercises-dataset/main/videos/2144-nIR4Rwl.gif', TRUE, 'weight_reps'),
  ('ex_cable_standing_up_straight_crossovers', 'Na kladce ve stoje up straight crossovers', 'Hrudník', '{"Ramena","Triceps"}', 'Stand in the middle of a cable machine with your feet shoulder-width apart. Hold the handles of the cables with your palms facing down and your arms extended straight out to the sides. Keeping your arms straight, bring your hands together in front of your body, crossing them over each other.', 'https://raw.githubusercontent.com/hasaneyldrm/exercises-dataset/main/videos/1269-UKWTJWR.gif', TRUE, 'weight_reps'),
  ('ex_alternate_lateral_pulldown', 'Alternate lateral Stahování horní kladky', 'Záda', '{"Biceps","rhomboids"}', 'Sit on the cable machine with your back straight and feet flat on the ground. Grasp the handles with an overhand grip, slightly wider than shoulder-width apart. Lean back slightly and pull the handles towards your chest, squeezing your shoulder blades together.', 'https://raw.githubusercontent.com/hasaneyldrm/exercises-dataset/main/videos/0007-4IKbhHV.gif', TRUE, 'weight_reps'),
  ('ex_archer_pull_up', 'Lukostřelecké shyby (Archer Pull-up)', 'Záda', '{"Biceps","Předloktí"}', 'Start by hanging from a pull-up bar with an overhand grip, slightly wider than shoulder-width apart. Engage your core and pull your shoulder blades down and back. As you pull yourself up, bend one arm and bring your elbow towards your side, while keeping the other arm straight.', 'https://raw.githubusercontent.com/hasaneyldrm/exercises-dataset/main/videos/3293-72BC5Za.gif', TRUE, 'reps_only'),
  ('ex_assisted_parallel_close_grip_pull_up', 'Assisted parallel úzkým úchopem Shyby', 'Záda', '{"Biceps","Předloktí"}', 'Adjust the machine to your desired weight and height. Place your hands on the parallel bars with a close grip, palms facing each other. Hang from the bars with your arms fully extended and your feet off the ground.', 'https://raw.githubusercontent.com/hasaneyldrm/exercises-dataset/main/videos/0015-vrhHa6D.gif', TRUE, 'weight_reps'),
  ('ex_assisted_pull_up', 'Assisted Shyby', 'Záda', '{"Biceps","Předloktí"}', 'Adjust the machine to your desired weight and height settings. Grasp the handles with an overhand grip, slightly wider than shoulder-width apart. Hang with your arms fully extended and your feet off the ground.', 'https://raw.githubusercontent.com/hasaneyldrm/exercises-dataset/main/videos/0017-kiJ4Z2K.gif', TRUE, 'weight_reps'),
  ('ex_assisted_standing_chin_up', 'Assisted ve stoje Shyby podhmatem', 'Záda', '{"Biceps","Předloktí"}', 'Adjust the machine to your desired assistance level. Stand on the foot platform and grip the handles with an overhand grip, slightly wider than shoulder-width apart. Keep your chest up and shoulders back, engage your core, and slightly bend your knees.', 'https://raw.githubusercontent.com/hasaneyldrm/exercises-dataset/main/videos/1431-7OeHptV.gif', TRUE, 'weight_reps'),
  ('ex_assisted_standing_pull_up', 'Assisted ve stoje Shyby', 'Záda', '{"Biceps","Předloktí"}', 'Adjust the machine to your desired weight and height settings. Stand facing the machine with your feet shoulder-width apart. Grasp the handles with an overhand grip, slightly wider than shoulder-width apart.', 'https://raw.githubusercontent.com/hasaneyldrm/exercises-dataset/main/videos/1432-f4xtKBj.gif', TRUE, 'weight_reps'),
  ('ex_back_lever', 'Back lever', 'Záda', '{"Biceps","Předloktí","Střed těla"}', 'Start by hanging from a pull-up bar with an overhand grip, hands slightly wider than shoulder-width apart. Engage your core and pull your shoulder blades down and back. Bend your knees and tuck them towards your chest.', 'https://raw.githubusercontent.com/hasaneyldrm/exercises-dataset/main/videos/3297-GaSzzuh.gif', TRUE, 'reps_only'),
  ('ex_back_pec_stretch', 'Back pec stretch', 'Záda', '{"Ramena","Hrudník"}', 'Stand tall with your feet shoulder-width apart. Extend your arms straight out in front of you, parallel to the ground. Cross your arms in front of your body, with your right arm over your left arm.', 'https://raw.githubusercontent.com/hasaneyldrm/exercises-dataset/main/videos/1405-chfnQnM.gif', TRUE, 'reps_only'),
  ('ex_barbell_bent_arm_pullover', 'S Velkou činkou (VČ) bent arm Pullover', 'Záda', '{"Triceps","Hrudník"}', 'Lie flat on a bench with your head at one end and your feet on the floor. Hold a barbell with a shoulder-width grip and extend your arms straight above your chest. Lower the barbell behind your head while keeping your arms slightly bent.', 'https://raw.githubusercontent.com/hasaneyldrm/exercises-dataset/main/videos/1316-cA9FuWG.gif', TRUE, 'weight_reps'),
  ('ex_barbell_decline_bent_arm_pullover', 'S Velkou činkou (VČ) hlavou dolů bent arm Pullover', 'Záda', '{"Triceps","Hrudník"}', 'Lie down on a decline bench with your head lower than your hips and your feet secured. Hold a barbell with a pronated grip (palms facing away from you) and extend your arms straight above your chest. Lower the barbell behind your head in a controlled manner, keeping your arms slightly bent.', 'https://raw.githubusercontent.com/hasaneyldrm/exercises-dataset/main/videos/0034-hMEptv0.gif', TRUE, 'weight_reps'),
  ('ex_barbell_decline_wide_grip_pullover', 'S Velkou činkou (VČ) hlavou dolů širokým úchopem Pullover', 'Záda', '{"Triceps","Hrudník"}', 'Lie on a decline bench with your head lower than your hips and your feet secured. Hold a barbell with a wide grip and extend your arms straight above your chest. Lower the barbell behind your head in a controlled manner, keeping your arms straight.', 'https://raw.githubusercontent.com/hasaneyldrm/exercises-dataset/main/videos/0037-Hj4FOCd.gif', TRUE, 'weight_reps'),
  ('ex_barbell_incline_row', 'S Velkou činkou (VČ) šikmo nahoru Přítahy', 'Záda', '{"Biceps","Předloktí"}', 'Set up an incline bench at a 45-degree angle. Lie face down on the bench with your chest against the pad and your feet flat on the ground. Grasp the barbell with an overhand grip, slightly wider than shoulder-width apart.', 'https://raw.githubusercontent.com/hasaneyldrm/exercises-dataset/main/videos/0049-dmgMp3n.gif', TRUE, 'weight_reps'),
  ('ex_barbell_one_arm_bent_over_row', 'S Velkou činkou (VČ) jednoruč Přítahy v předklonu', 'Záda', '{"Biceps","Předloktí"}', 'Stand with your feet shoulder-width apart, knees slightly bent, and hold a barbell with one hand using an overhand grip. Bend forward at the hips, keeping your back straight and your head in a neutral position. Pull the barbell up towards your chest, keeping your elbow close to your body and squeezing your shoulder blades together.', 'https://raw.githubusercontent.com/hasaneyldrm/exercises-dataset/main/videos/0064-Jsgsc27.gif', TRUE, 'weight_reps'),
  ('ex_barbell_pendlay_row', 'Pendlay přítahy z podlahy', 'Záda', '{"Biceps","Předloktí"}', 'Stand with your feet shoulder-width apart and your knees slightly bent. Bend forward at the hips, keeping your back straight and your chest up. Grasp the barbell with an overhand grip, slightly wider than shoulder-width apart.', 'https://raw.githubusercontent.com/hasaneyldrm/exercises-dataset/main/videos/3017-r0z6xzQ.gif', TRUE, 'weight_reps'),
  ('ex_barbell_pullover', 'S Velkou činkou (VČ) Pullover', 'Záda', '{"Hrudník","Triceps"}', 'Lie flat on a bench with your head at one end and your feet on the floor. Hold a barbell with a shoulder-width grip and extend your arms straight above your chest. Keeping your arms straight, lower the barbell behind your head in a controlled manner until you feel a stretch in your lats.', 'https://raw.githubusercontent.com/hasaneyldrm/exercises-dataset/main/videos/0073-i6LWjok.gif', TRUE, 'weight_reps'),
  ('ex_barbell_pullover_to_press', 'S Velkou činkou (VČ) Pullover to Tlaky', 'Záda', '{"Triceps","Hrudník","Ramena"}', 'Lie flat on a bench with your head at one end and your feet on the ground. Hold the barbell with a pronated grip (palms facing away from you) and extend your arms straight above your chest. Keeping your arms straight, lower the barbell behind your head in an arc-like motion until you feel a stretch in your lats.', 'https://raw.githubusercontent.com/hasaneyldrm/exercises-dataset/main/videos/0022-znLogoF.gif', TRUE, 'weight_reps'),
  ('ex_barbell_reverse_grip_incline_bench_row', 'S Velkou činkou (VČ) podhmatem šikmo nahoru bench Přítahy', 'Záda', '{"Biceps","Předloktí"}', 'Set up an incline bench at a 45-degree angle. Sit on the bench facing the backrest with your chest against it. Grab the barbell with a reverse grip (palms facing down) and hands slightly wider than shoulder-width apart.', 'https://raw.githubusercontent.com/hasaneyldrm/exercises-dataset/main/videos/1317-8d8qJQI.gif', TRUE, 'weight_reps'),
  ('ex_bench_pull_ups', 'Bench Shyby', 'Záda', '{"Biceps","Předloktí"}', 'Position yourself under a bar or a sturdy horizontal surface that is at chest height. Grab the bar or surface with an overhand grip, slightly wider than shoulder-width apart. Hang with your arms fully extended and your body straight.', 'https://raw.githubusercontent.com/hasaneyldrm/exercises-dataset/main/videos/3019-mExgrF9.gif', TRUE, 'reps_only'),
  ('ex_bodyweight_squatting_row', 'Bodyweight squatting Přítahy', 'Záda', '{"Biceps","Ramena"}', 'Stand with your feet shoulder-width apart, holding onto a sturdy object or suspension trainer with your arms extended. Lower your body into a squat position, keeping your back straight and your knees behind your toes. From the squat position, pull your body up towards the object or suspension trainer, squeezing your shoulder blades together.', 'https://raw.githubusercontent.com/hasaneyldrm/exercises-dataset/main/videos/3168-3xK09Sk.gif', TRUE, 'reps_only'),
  ('ex_bodyweight_standing_close_grip_one_arm_row', 'Bodyweight ve stoje úzkým úchopem jednoruč Přítahy', 'Záda', '{"Biceps","Předloktí"}', 'Stand with your feet shoulder-width apart, knees slightly bent, and hold a dumbbell in one hand with a neutral grip. Bend forward at the hips, keeping your back straight and your core engaged. Pull the dumbbell up towards your chest, keeping your elbow close to your body and squeezing your shoulder blades together.', 'https://raw.githubusercontent.com/hasaneyldrm/exercises-dataset/main/videos/3156-v2DfH14.gif', TRUE, 'reps_only'),
  ('ex_bodyweight_standing_close_grip_row', 'Bodyweight ve stoje úzkým úchopem Přítahy', 'Záda', '{"Biceps","Předloktí"}', 'Stand with your feet shoulder-width apart and knees slightly bent. Bend forward at the waist, keeping your back straight and your core engaged. Extend your arms straight in front of you, gripping the bar or handles with a close grip.', 'https://raw.githubusercontent.com/hasaneyldrm/exercises-dataset/main/videos/3158-tig3PXb.gif', TRUE, 'reps_only'),
  ('ex_bodyweight_standing_one_arm_row', 'Bodyweight ve stoje jednoruč Přítahy', 'Záda', '{"Biceps","Předloktí"}', 'Stand with your feet shoulder-width apart, knees slightly bent, and hold a dumbbell in one hand. Bend forward at the hips, keeping your back straight and your core engaged. Let the dumbbell hang straight down in front of you, with your arm fully extended.', 'https://raw.githubusercontent.com/hasaneyldrm/exercises-dataset/main/videos/3162-xbkPfaw.gif', TRUE, 'reps_only'),
  ('ex_bodyweight_standing_row', 'Bodyweight ve stoje Přítahy', 'Záda', '{"Biceps","Ramena"}', 'Stand with your feet shoulder-width apart and knees slightly bent. Grasp a bar or handles with an overhand grip, palms facing down. Keep your back straight and core engaged.', 'https://raw.githubusercontent.com/hasaneyldrm/exercises-dataset/main/videos/3166-wd4ds3s.gif', TRUE, 'reps_only'),
  ('ex_cable_bar_lateral_pulldown', 'Na kladce bar lateral Stahování horní kladky', 'Záda', '{"Biceps","rhomboids","rear deltoids"}', 'Adjust the cable pulley to a high position and attach a straight bar. Sit facing the cable machine with your feet flat on the ground and your knees slightly bent. Grasp the bar with an overhand grip, slightly wider than shoulder-width apart.', 'https://raw.githubusercontent.com/hasaneyldrm/exercises-dataset/main/videos/0150-eYnzaCm.gif', TRUE, 'weight_reps'),
  ('ex_cable_cross_over_lateral_pulldown', 'Na kladce křížení kladek lateral Stahování horní kladky', 'Záda', '{"Biceps","rhomboids","rear deltoids"}', 'Attach a cable handle to each side of a cable machine at shoulder height. Stand in the middle of the machine with your feet shoulder-width apart. Grasp the handles with an overhand grip and step back to create tension in the cables.', 'https://raw.githubusercontent.com/hasaneyldrm/exercises-dataset/main/videos/0153-OQ1otBN.gif', TRUE, 'weight_reps'),
  ('ex_cable_decline_seated_wide_grip_row', 'Na kladce hlavou dolů v sedě širokým úchopem Přítahy', 'Záda', '{"Biceps","Předloktí"}', 'Sit on the decline bench facing the cable machine with your feet securely placed on the footrests. Grasp the cable attachment with a wide overhand grip, palms facing down. Lean back slightly, keeping your back straight and your core engaged.', 'https://raw.githubusercontent.com/hasaneyldrm/exercises-dataset/main/videos/0159-kesXOpB.gif', TRUE, 'weight_reps'),
  ('ex_cable_floor_seated_wide_grip_row', 'Na kladce floor v sedě širokým úchopem Přítahy', 'Záda', '{"Biceps","Předloktí"}', 'Sit on the floor with your legs extended and your back straight. Attach a cable handle to a low pulley and position the cable machine behind you. Grasp the handle with a wide overhand grip, palms facing down.', 'https://raw.githubusercontent.com/hasaneyldrm/exercises-dataset/main/videos/0160-veXwo0D.gif', TRUE, 'weight_reps'),
  ('ex_cable_high_row_kneeling', 'Na kladce high Přítahy (v kleče)', 'Záda', '{"Biceps","Ramena"}', 'Attach a straight bar to a cable machine at chest height. Kneel down in front of the cable machine and grab the bar with an overhand grip, hands shoulder-width apart. Sit back on your heels, keeping your back straight and your core engaged.', 'https://raw.githubusercontent.com/hasaneyldrm/exercises-dataset/main/videos/0167-ZSJNetl.gif', TRUE, 'weight_reps'),
  ('ex_cable_incline_bench_row', 'Na kladce šikmo nahoru bench Přítahy', 'Záda', '{"Biceps","rear deltoids"}', 'Set up an incline bench at a 45-degree angle and attach a cable handle to the low pulley. Sit on the bench facing the cable machine with your feet flat on the floor and your knees slightly bent. Grasp the cable handle with an overhand grip and extend your arms fully in front of you.', 'https://raw.githubusercontent.com/hasaneyldrm/exercises-dataset/main/videos/1318-yaMIo4D.gif', TRUE, 'weight_reps'),
  ('ex_cable_incline_pushdown', 'Na kladce šikmo nahoru Stahování kladky', 'Záda', '{"Triceps","Ramena"}', 'Attach a straight bar to a high pulley cable machine. Stand facing away from the machine with your feet shoulder-width apart. Grasp the bar with an overhand grip, hands slightly wider than shoulder-width apart.', 'https://raw.githubusercontent.com/hasaneyldrm/exercises-dataset/main/videos/0172-1PK5Uo3.gif', TRUE, 'weight_reps'),
  ('ex_cable_lat_pulldown_full_range_of_motion', 'Na kladce Stahování horní kladky na záda full range of motion', 'Záda', '{"Biceps","rhomboids","rear deltoids"}', 'Sit on the lat pulldown machine with your knees positioned under the pads. Grasp the cable bar with an overhand grip, slightly wider than shoulder-width apart. Lean back slightly and keep your chest up, maintaining a slight arch in your lower back.', 'https://raw.githubusercontent.com/hasaneyldrm/exercises-dataset/main/videos/2330-LEprlgG.gif', TRUE, 'weight_reps'),
  ('ex_cable_lateral_pulldown_with_rope_attachment', 'Na kladce lateral Stahování horní kladky (with rope attachment)', 'Záda', '{"Biceps","Předloktí"}', 'Attach a rope attachment to the cable machine at a high position. Stand facing the machine with your feet shoulder-width apart. Grasp the rope with an overhand grip, palms facing each other.', 'https://raw.githubusercontent.com/hasaneyldrm/exercises-dataset/main/videos/0177-CuaWCmC.gif', TRUE, 'weight_reps'),
  ('ex_cable_lateral_pulldown_with_v_bar', 'Na kladce lateral Stahování horní kladky with v-bar', 'Záda', '{"Biceps","Předloktí"}', 'Sit down on the cable pulldown machine and grab the v-bar attachment with an overhand grip. Adjust the knee pad so that your thighs are secured under it. Keep your back straight and lean back slightly.', 'https://raw.githubusercontent.com/hasaneyldrm/exercises-dataset/main/videos/2616-4c9BhzB.gif', TRUE, 'weight_reps'),
  ('ex_cable_lying_extension_pullover_with_rope_attachment', 'Na kladce v leže Extenze Pullover (with rope attachment)', 'Záda', '{"Triceps","Ramena"}', 'Attach a rope to a cable machine and set the pulley at the highest position. Lie down on a bench with your head towards the cable machine. Hold the rope with both hands and extend your arms straight up above your chest.', 'https://raw.githubusercontent.com/hasaneyldrm/exercises-dataset/main/videos/0184-Q2Eu1Ax.gif', TRUE, 'weight_reps'),
  ('ex_cable_one_arm_bent_over_row', 'Na kladce jednoruč Přítahy v předklonu', 'Záda', '{"Biceps","Předloktí"}', 'Stand facing a cable machine with your feet shoulder-width apart. Bend your knees slightly and hinge forward at the hips, keeping your back straight. Grasp the cable handle with one hand, palm facing inward, and extend your arm fully.', 'https://raw.githubusercontent.com/hasaneyldrm/exercises-dataset/main/videos/0189-EIsE3u8.gif', TRUE, 'weight_reps'),
  ('ex_cable_one_arm_pulldown', 'Na kladce jednoruč Stahování horní kladky', 'Záda', '{"Biceps","Předloktí"}', 'Attach a single handle to a high pulley cable machine. Stand facing the machine with your feet shoulder-width apart. Grasp the handle with an overhand grip and extend your arm fully.', 'https://raw.githubusercontent.com/hasaneyldrm/exercises-dataset/main/videos/3563-U5INZY6.gif', TRUE, 'weight_reps'),
  ('ex_cable_one_arm_straight_back_high_row_kneeling', 'Na kladce jednoruč straight back high Přítahy (v kleče)', 'Záda', '{"Biceps","Ramena"}', 'Attach a handle to a cable machine at waist height. Kneel down facing the cable machine and grab the handle with one hand. Keep your back straight and your core engaged.', 'https://raw.githubusercontent.com/hasaneyldrm/exercises-dataset/main/videos/0193-WrYPP2g.gif', TRUE, 'weight_reps'),
  ('ex_cable_palm_rotational_row', 'Na kladce palm rotational Přítahy', 'Záda', '{"Biceps","Předloktí"}', 'Attach a handle to a cable machine at waist height. Stand facing the machine with your feet shoulder-width apart. Grasp the handle with an overhand grip, palms facing down.', 'https://raw.githubusercontent.com/hasaneyldrm/exercises-dataset/main/videos/1319-OmQ8w0p.gif', TRUE, 'weight_reps'),
  ('ex_cable_pulldown_pro_lat_bar', 'Na kladce Stahování horní kladky (pro lat bar)', 'Záda', '{"Biceps","Předloktí"}', 'Adjust the seat height so that your thighs are parallel to the ground and your feet are flat on the floor. Grasp the lat bar with an overhand grip, slightly wider than shoulder-width apart. Sit down and lean back slightly, keeping your chest up and your back straight.', 'https://raw.githubusercontent.com/hasaneyldrm/exercises-dataset/main/videos/0197-qdRxqCj.gif', TRUE, 'weight_reps'),
  ('ex_cable_pushdown_straight_arm_v_2', 'Na kladce Stahování kladky (straight arm) v. 2', 'Záda', '{"Triceps","Ramena"}', 'Attach a straight bar to a high pulley cable machine. Stand facing the machine with your feet shoulder-width apart and a slight bend in your knees. Grasp the bar with an overhand grip, keeping your arms straight and your palms facing down.', 'https://raw.githubusercontent.com/hasaneyldrm/exercises-dataset/main/videos/0199-PskORrA.gif', TRUE, 'weight_reps'),
  ('ex_barbell_one_arm_snatch', 'S Velkou činkou (VČ) jednoruč snatch', 'Ramena', '{"Trapézy","Předloktí","Střed těla"}', 'Stand with your feet shoulder-width apart, toes pointing slightly outwards. Hold the barbell with an overhand grip, hands slightly wider than shoulder-width apart. Bend your knees and lower your hips into a squat position, keeping your back straight and chest up.', 'https://raw.githubusercontent.com/hasaneyldrm/exercises-dataset/main/videos/0067-xHKN2s8.gif', TRUE, 'weight_reps'),
  ('ex_barbell_rear_delt_raise', 'S Velkou činkou (VČ) na zadní delty raise', 'Ramena', '{"Trapézy","rhomboids"}', 'Stand with your feet shoulder-width apart and hold a barbell with an overhand grip, palms facing down. Bend your knees slightly and hinge forward at the hips, keeping your back straight. Raise the barbell out to the sides, keeping your arms straight, until they are parallel to the ground.', 'https://raw.githubusercontent.com/hasaneyldrm/exercises-dataset/main/videos/0075-Ln9iTbU.gif', TRUE, 'weight_reps'),
  ('ex_barbell_rear_delt_row', 'S Velkou činkou (VČ) na zadní delty Přítahy', 'Ramena', '{"trapezius","rhomboids","Biceps"}', 'Stand with your feet shoulder-width apart and knees slightly bent. Hold a barbell with an overhand grip, hands slightly wider than shoulder-width apart. Bend forward at the hips, keeping your back straight and chest up.', 'https://raw.githubusercontent.com/hasaneyldrm/exercises-dataset/main/videos/0076-S9zHIvU.gif', TRUE, 'weight_reps'),
  ('ex_barbell_seated_behind_head_military_press', 'S Velkou činkou (VČ) v sedě behind head military Tlaky', 'Ramena', '{"Triceps","Mezilopatkové svaly"}', 'Sit on a bench with your back straight and feet flat on the ground. Hold the barbell with an overhand grip, slightly wider than shoulder-width apart. Lift the barbell off the rack and bring it down to shoulder level, behind your head.', 'https://raw.githubusercontent.com/hasaneyldrm/exercises-dataset/main/videos/0086-ngPpyRS.gif', TRUE, 'weight_reps'),
  ('ex_barbell_seated_bradford_rocky_press', 'S Velkou činkou (VČ) v sedě bradford rocky Tlaky', 'Ramena', '{"Triceps","Mezilopatkové svaly"}', 'Sit on a bench with your back straight and feet flat on the ground. Hold the barbell with an overhand grip, slightly wider than shoulder-width apart. Lift the barbell to shoulder height, keeping your elbows slightly bent and pointing forward.', 'https://raw.githubusercontent.com/hasaneyldrm/exercises-dataset/main/videos/0087-0dCyly0.gif', TRUE, 'weight_reps'),
  ('ex_barbell_skier', 'S Velkou činkou (VČ) skier', 'Ramena', '{"Triceps","Střed těla"}', 'Stand with your feet shoulder-width apart and hold a barbell in front of your thighs with an overhand grip. Bend your knees slightly and hinge forward at the hips, keeping your back straight and chest up. Simultaneously lift the barbell up towards your shoulders while jumping slightly off the ground.', 'https://raw.githubusercontent.com/hasaneyldrm/exercises-dataset/main/videos/0100-4Leypho.gif', TRUE, 'weight_reps'),
  ('ex_barbell_standing_bradford_press', 'S Velkou činkou (VČ) ve stoje bradford Tlaky', 'Ramena', '{"Triceps","Mezilopatkové svaly"}', 'Stand with your feet shoulder-width apart and hold the barbell in front of your shoulders with an overhand grip. Press the barbell overhead, fully extending your arms. Lower the barbell back down to the starting position.', 'https://raw.githubusercontent.com/hasaneyldrm/exercises-dataset/main/videos/0105-dCPESfR.gif', TRUE, 'weight_reps'),
  ('ex_barbell_standing_close_grip_military_press', 'S Velkou činkou (VČ) ve stoje úzkým úchopem military Tlaky', 'Ramena', '{"Triceps","Mezilopatkové svaly"}', 'Stand with your feet shoulder-width apart and hold the barbell with an overhand grip, hands slightly closer than shoulder-width apart. Lift the barbell to shoulder height, keeping your elbows close to your body. Press the barbell overhead, extending your arms fully.', 'https://raw.githubusercontent.com/hasaneyldrm/exercises-dataset/main/videos/1456-wdRZISl.gif', TRUE, 'weight_reps'),
  ('ex_barbell_standing_front_raise_over_head', 'S Velkou činkou (VČ) ve stoje Předpažování over head', 'Ramena', '{"Triceps","Mezilopatkové svaly"}', 'Stand with your feet shoulder-width apart, holding a barbell in front of your thighs with an overhand grip. Keep your back straight and engage your core. Slowly raise the barbell in front of you, keeping your arms straight and your palms facing down.', 'https://raw.githubusercontent.com/hasaneyldrm/exercises-dataset/main/videos/0107-S8mo30S.gif', TRUE, 'weight_reps'),
  ('ex_barbell_standing_wide_military_press', 'S Velkou činkou (VČ) ve stoje širokým úchopem military Tlaky', 'Ramena', '{"Triceps","Mezilopatkové svaly"}', 'Stand with your feet shoulder-width apart and hold the barbell with an overhand grip, slightly wider than shoulder-width. Lift the barbell to shoulder height, keeping your elbows slightly in front of the bar. Press the barbell overhead, extending your arms fully.', 'https://raw.githubusercontent.com/hasaneyldrm/exercises-dataset/main/videos/1457-Kyd9Rz5.gif', TRUE, 'weight_reps'),
  ('ex_barbell_thruster', 'S Velkou činkou (VČ) thruster', 'Ramena', '{"Kvadricepsy","Hýždě","Hamstringy"}', 'Start by standing with your feet shoulder-width apart, holding a barbell at shoulder height with an overhand grip. Lower into a squat position by bending your knees and pushing your hips back. As you reach the bottom of the squat, explosively drive through your heels to stand up, simultaneously pressing the barbell overhead.', 'https://raw.githubusercontent.com/hasaneyldrm/exercises-dataset/main/videos/3305-f7Y9eDZ.gif', TRUE, 'weight_reps'),
  ('ex_barbell_upright_row', 'S Velkou činkou (VČ) upright Přítahy', 'Ramena', '{"Trapézy","Biceps"}', 'Stand with your feet shoulder-width apart and hold a barbell with an overhand grip, hands slightly wider than shoulder-width apart. Let the barbell hang in front of your thighs, arms fully extended. Keeping your back straight and core engaged, exhale and lift the barbell straight up towards your chin, leading with your elbows.', 'https://raw.githubusercontent.com/hasaneyldrm/exercises-dataset/main/videos/0120-UDlhcO8.gif', TRUE, 'weight_reps'),
  ('ex_barbell_upright_row_v_3', 'S Velkou činkou (VČ) upright Přítahy v. 3', 'Ramena', '{"Trapézy","Biceps"}', 'Stand with your feet shoulder-width apart and hold a barbell with an overhand grip, hands slightly wider than shoulder-width apart. Let the barbell hang in front of your thighs, arms fully extended. Keeping your core engaged and back straight, exhale as you lift the barbell straight up towards your chin, leading with your elbows.', 'https://raw.githubusercontent.com/hasaneyldrm/exercises-dataset/main/videos/0121-fI18Rbc.gif', TRUE, 'weight_reps'),
  ('ex_barbell_wide_grip_upright_row', 'S Velkou činkou (VČ) širokým úchopem upright Přítahy', 'Ramena', '{"Trapézy","Biceps"}', 'Stand with your feet shoulder-width apart and hold a barbell with an overhand grip, hands wider than shoulder-width apart. Let the barbell hang in front of your thighs, arms fully extended. Keeping your back straight, exhale and lift the barbell straight up towards your chin, leading with your elbows.', 'https://raw.githubusercontent.com/hasaneyldrm/exercises-dataset/main/videos/0123-RgJDRR1.gif', TRUE, 'weight_reps'),
  ('ex_cable_alternate_shoulder_press', 'Na kladce alternate Tlaky na ramena', 'Ramena', '{"Triceps","Mezilopatkové svaly"}', 'Stand with your feet shoulder-width apart and grasp the handles of the cable machine with an overhand grip. Position your hands at shoulder height, with your palms facing forward. Keep your core engaged and your back straight.', 'https://raw.githubusercontent.com/hasaneyldrm/exercises-dataset/main/videos/0148-KHPZL0b.gif', TRUE, 'weight_reps'),
  ('ex_cable_cross_over_revers_fly', 'Na kladce křížení kladek revers Rozpažování', 'Ramena', '{"rhomboids","trapezius"}', 'Attach a D-handle to each low pulley cable and stand in the middle of the cable crossover machine. Grasp the handles with a pronated grip (palms facing down) and take a step forward, positioning your feet shoulder-width apart. Bend your knees slightly and lean forward at the waist, keeping your back straight and your abs engaged.', 'https://raw.githubusercontent.com/hasaneyldrm/exercises-dataset/main/videos/0154-aqvSOQE.gif', TRUE, 'weight_reps'),
  ('ex_cable_forward_raise', 'Na kladce forward raise', 'Ramena', '{"Triceps","Předloktí"}', 'Stand with your feet shoulder-width apart and your knees slightly bent. Hold the cable handle with an overhand grip, palms facing down, and your arms fully extended in front of you. Keeping your arms straight, raise the cable handle up to shoulder level.', 'https://raw.githubusercontent.com/hasaneyldrm/exercises-dataset/main/videos/0161-hvHhCv8.gif', TRUE, 'weight_reps'),
  ('ex_cable_front_raise', 'Na kladce Předpažování', 'Ramena', '{"Triceps","Předloktí"}', 'Stand with your feet shoulder-width apart and grasp the cable handle with an overhand grip. Keep your back straight and your core engaged. Raise the cable handle in front of you, keeping your arms straight and your palms facing down.', 'https://raw.githubusercontent.com/hasaneyldrm/exercises-dataset/main/videos/0162-u2X71Np.gif', TRUE, 'weight_reps'),
  ('ex_cable_kneeling_rear_delt_row_with_rope_male', 'Na kladce v kleče na zadní delty Přítahy (with rope) (male)', 'Ramena', '{"trapezius","rhomboids","Biceps"}', 'Attach a rope handle to a low cable pulley and kneel down facing the machine. Grasp the rope with a neutral grip (palms facing each other) and extend your arms fully in front of you. Keeping your back straight and core engaged, pull the rope towards your body by retracting your shoulder blades.', 'https://raw.githubusercontent.com/hasaneyldrm/exercises-dataset/main/videos/3697-G61cXLk.gif', TRUE, 'weight_reps'),
  ('ex_cable_lateral_raise', 'Na kladce Upažování na ramena', 'Ramena', '{"Trapézy","Triceps"}', 'Stand with your feet shoulder-width apart and grasp the cable handles with an overhand grip. Keep your arms straight and your core engaged. Raise your arms out to the sides until they are parallel to the floor.', 'https://raw.githubusercontent.com/hasaneyldrm/exercises-dataset/main/videos/0178-goJ6ezq.gif', TRUE, 'weight_reps'),
  ('ex_cable_one_arm_lateral_raise', 'Na kladce jednoruč Upažování na ramena', 'Ramena', '{"Trapézy","Triceps"}', 'Stand with your feet shoulder-width apart, facing the cable machine. Hold the cable handle with one hand, palm facing down, and stand far enough away from the machine so that there is tension on the cable. Keep your arm straight and slowly raise it out to the side until it is parallel to the ground.', 'https://raw.githubusercontent.com/hasaneyldrm/exercises-dataset/main/videos/0192-wEulIzp.gif', TRUE, 'weight_reps'),
  ('ex_cable_rear_delt_row_stirrups', 'Na kladce na zadní delty Přítahy (stirrups)', 'Ramena', '{"trapezius","rhomboids","Biceps"}', 'Attach a stirrup handle to a low cable pulley and stand facing the machine. Grasp the handle with your left hand and take a step back with your right foot, positioning your body at a slight angle. Bend your knees slightly and hinge forward at the hips, keeping your back straight and your core engaged.', 'https://raw.githubusercontent.com/hasaneyldrm/exercises-dataset/main/videos/0202-yUdIGNs.gif', TRUE, 'weight_reps'),
  ('ex_cable_rear_delt_row_with_rope', 'Na kladce na zadní delty Přítahy (with rope)', 'Ramena', '{"trapezius","rhomboids","Biceps"}', 'Attach a rope handle to a low pulley cable machine. Stand facing the machine with your feet shoulder-width apart. Grasp the rope handle with an overhand grip, palms facing each other.', 'https://raw.githubusercontent.com/hasaneyldrm/exercises-dataset/main/videos/0203-wqNPGCg.gif', TRUE, 'weight_reps'),
  ('ex_cable_seated_rear_lateral_raise', 'Na kladce v sedě rear Upažování na ramena', 'Ramena', '{"Trapézy","rhomboids"}', 'Sit on a bench facing the cable machine with your feet flat on the ground. Grasp the cable handles with an overhand grip and extend your arms straight in front of you. Keeping your arms straight, slowly raise them out to the sides until they are parallel to the floor.', 'https://raw.githubusercontent.com/hasaneyldrm/exercises-dataset/main/videos/0215-x825CZm.gif', TRUE, 'weight_reps'),
  ('ex_cable_seated_shoulder_internal_rotation', 'Na kladce v sedě shoulder internal rotation', 'Ramena', '{"rotator cuff","Triceps"}', 'Sit on a bench or chair facing the cable machine with your feet flat on the ground. Hold the cable handle with your arm extended straight out in front of you, parallel to the ground. Keep your elbow slightly bent and your shoulder blades pulled back and down.', 'https://raw.githubusercontent.com/hasaneyldrm/exercises-dataset/main/videos/0216-YPoVrBi.gif', TRUE, 'weight_reps'),
  ('ex_cable_shoulder_press', 'Na kladce Tlaky na ramena', 'Ramena', '{"Triceps","Mezilopatkové svaly"}', 'Adjust the cable machine so that the handles are at shoulder height. Stand facing away from the machine with your feet shoulder-width apart. Grasp the handles with an overhand grip and bring them up to shoulder level, with your elbows bent and pointing outwards.', 'https://raw.githubusercontent.com/hasaneyldrm/exercises-dataset/main/videos/0219-PzQanLE.gif', TRUE, 'weight_reps'),
  ('ex_cable_standing_rear_delt_row_with_rope', 'Na kladce ve stoje na zadní delty Přítahy (with rope)', 'Ramena', '{"trapezius","rhomboids","Biceps"}', 'Stand facing a cable machine with your feet shoulder-width apart. Hold the cable attachment with both hands, palms facing each other, and step back to create tension in the cable. Keep your back straight and your core engaged.', 'https://raw.githubusercontent.com/hasaneyldrm/exercises-dataset/main/videos/0233-ZfyAGhK.gif', TRUE, 'weight_reps'),
  ('ex_cable_standing_shoulder_external_rotation', 'Na kladce ve stoje shoulder external rotation', 'Ramena', '{"rotator cuff","trapezius"}', 'Stand with your feet shoulder-width apart and your knees slightly bent. Hold the cable handle with your arm extended in front of you, parallel to the ground. Keep your elbow slightly bent and your shoulder blades pulled back.', 'https://raw.githubusercontent.com/hasaneyldrm/exercises-dataset/main/videos/0235-FWdVhcW.gif', TRUE, 'weight_reps'),
  ('ex_cable_supine_reverse_fly', 'Na kladce supine reverse Rozpažování', 'Ramena', '{"trapezius","rhomboids"}', 'Attach a D-handle to a low pulley cable machine and lie face down on a flat bench. Grasp the D-handle with each hand, palms facing down, and extend your arms straight out in front of you. Keeping your arms straight, raise them out to the sides until they are parallel to the floor.', 'https://raw.githubusercontent.com/hasaneyldrm/exercises-dataset/main/videos/0240-PQcUlDi.gif', TRUE, 'weight_reps'),
  ('ex_cable_upright_row', 'Na kladce upright Přítahy', 'Ramena', '{"Trapézy","Biceps"}', 'Stand with your feet shoulder-width apart, knees slightly bent, and hold the cable attachment with an overhand grip. Keep your back straight and your core engaged throughout the exercise. Pull the cable attachment straight up towards your chin, leading with your elbows.', 'https://raw.githubusercontent.com/hasaneyldrm/exercises-dataset/main/videos/0246-cALKspW.gif', TRUE, 'weight_reps'),
  ('ex_dumbbell_arnold_press', 'S Jednoručkou (JČ) arnold Tlaky', 'Ramena', '{"Triceps","upper chest"}', 'Sit on a bench with back support and hold a dumbbell in each hand at shoulder level, palms facing your body and elbows bent. Press the dumbbells upward until your arms are fully extended and your palms are facing forward. Rotate your wrists as you lift, so that your palms are facing forward at the top of the movement.', 'https://raw.githubusercontent.com/hasaneyldrm/exercises-dataset/main/videos/2137-Xy4jlWA.gif', TRUE, 'weight_reps'),
  ('ex_dumbbell_arnold_press_v_2', 'S Jednoručkou (JČ) arnold Tlaky v. 2', 'Ramena', '{"Triceps","upper chest"}', 'Sit on a bench with back support and hold a dumbbell in each hand at shoulder level, palms facing your body and elbows bent. Press the dumbbells upward until your arms are fully extended and your palms are facing forward. Rotate your wrists as you lift, so that your palms end up facing forward at the top of the movement.', 'https://raw.githubusercontent.com/hasaneyldrm/exercises-dataset/main/videos/0287-eOrFCnx.gif', TRUE, 'weight_reps'),
  ('ex_all_fours_squad_stretch', 'All fours squad stretch', 'Nohy', '{"Hamstringy","Hýždě"}', 'Start on all fours with your hands directly under your shoulders and your knees directly under your hips. Extend one leg straight back, keeping your knee bent and your foot flexed. Slowly lower your hips towards the ground, feeling a stretch in your quads.', 'https://raw.githubusercontent.com/hasaneyldrm/exercises-dataset/main/videos/1512-qBcKorM.gif', TRUE, 'reps_only'),
  ('ex_ankle_circles', 'Ankle circles', 'Nohy', '{"ankle stabilizers"}', 'Sit on the ground with your legs extended in front of you. Lift one leg off the ground and rotate your ankle in a circular motion. Perform the desired number of circles in one direction, then switch to the other direction.', 'https://raw.githubusercontent.com/hasaneyldrm/exercises-dataset/main/videos/1368-uL9CsKm.gif', TRUE, 'reps_only'),
  ('ex_arms_apart_circular_toe_touch_male', 'Arms apart circular toe touch (male)', 'Nohy', '{"Hamstringy","Kvadricepsy","Lýtka"}', 'Stand with your feet shoulder-width apart and arms extended to the sides. Keeping your legs straight, bend forward at the waist and reach down towards your toes with your right hand. As you reach down, simultaneously lift your left leg straight up behind you, maintaining balance.', 'https://raw.githubusercontent.com/hasaneyldrm/exercises-dataset/main/videos/3214-RtyAsy1.gif', TRUE, 'reps_only'),
  ('ex_backward_jump', 'Backward jump', 'Nohy', '{"Hamstringy","Hýždě","Lýtka"}', 'Stand with your feet shoulder-width apart. Bend your knees slightly and jump backwards, pushing off with both feet. Land softly on the balls of your feet, bending your knees to absorb the impact.', 'https://raw.githubusercontent.com/hasaneyldrm/exercises-dataset/main/videos/1473-SaDOwk7.gif', TRUE, 'reps_only'),
  ('ex_balance_board', 'Balance board', 'Nohy', '{"Lýtka","Hamstringy","Hýždě"}', 'Place the balance board on a flat surface. Step onto the balance board with one foot, ensuring it is centered. Slowly shift your weight onto the foot on the balance board, keeping your core engaged.', 'https://raw.githubusercontent.com/hasaneyldrm/exercises-dataset/main/videos/0020-xAySMB0.gif', TRUE, 'reps_only'),
  ('ex_barbell_bench_front_squat', 'S Velkou činkou (VČ) bench front Dřep', 'Nohy', '{"Hamstringy","Hýždě","Lýtka"}', 'Start by standing with your feet shoulder-width apart and the barbell resting on your upper chest, just below your collarbone. Hold the barbell with an overhand grip, keeping your elbows up and your upper arms parallel to the ground. Lower your body down into a squat position by bending at the knees and hips, keeping your back straight and your chest up.', 'https://raw.githubusercontent.com/hasaneyldrm/exercises-dataset/main/videos/0024-Y7YcmIJ.gif', TRUE, 'weight_reps'),
  ('ex_barbell_bench_squat', 'S Velkou činkou (VČ) bench Dřep', 'Nohy', '{"Hýždě","Hamstringy","Lýtka"}', 'Set up a barbell on a squat rack at chest height. Stand facing away from the rack, with your feet shoulder-width apart. Bend your knees and lower your body down into a squat position, keeping your back straight and chest up.', 'https://raw.githubusercontent.com/hasaneyldrm/exercises-dataset/main/videos/0026-W9pFVv1.gif', TRUE, 'weight_reps'),
  ('ex_barbell_clean_and_press', 'S Velkou činkou (VČ) clean a Tlaky', 'Nohy', '{"Hamstringy","Hýždě","Ramena"}', 'Stand with your feet shoulder-width apart and the barbell on the floor in front of you. Bend your knees and hinge at the hips to lower down and grip the barbell with an overhand grip, hands slightly wider than shoulder-width apart. Drive through your heels and extend your hips and knees to lift the barbell off the floor, keeping it close to your body.', 'https://raw.githubusercontent.com/hasaneyldrm/exercises-dataset/main/videos/0028-SGY8Zui.gif', TRUE, 'weight_reps'),
  ('ex_barbell_clean_grip_front_squat', 'S Velkou činkou (VČ) clean-grip front Dřep', 'Nohy', '{"Kvadricepsy","Hamstringy","Lýtka"}', 'Start by standing with your feet shoulder-width apart and the barbell resting on your upper chest, with your elbows pointing forward. Lower your body by bending your knees and pushing your hips back, as if you are sitting back into a chair. Keep your chest up and your back straight as you lower down, making sure your knees do not go past your toes.', 'https://raw.githubusercontent.com/hasaneyldrm/exercises-dataset/main/videos/0029-qi996YS.gif', TRUE, 'weight_reps'),
  ('ex_barbell_floor_calf_raise', 'S Velkou činkou (VČ) floor Výpony na lýtka', 'Nohy', '{"Hamstringy"}', 'Place a barbell on the floor in front of you. Stand with the balls of your feet on the edge of the barbell, with your heels hanging off. Hold onto a stable object for balance if needed.', 'https://raw.githubusercontent.com/hasaneyldrm/exercises-dataset/main/videos/1370-2IHEa2T.gif', TRUE, 'weight_reps'),
  ('ex_barbell_front_squat', 'S Velkou činkou (VČ) front Dřep', 'Nohy', '{"Kvadricepsy","Hamstringy","Lýtka"}', 'Start by standing with your feet shoulder-width apart, toes slightly turned out. Hold the barbell in front of your shoulders, resting it on your collarbone and shoulders. Engage your core and keep your chest up as you lower your body down into a squat position, pushing your hips back and bending your knees.', 'https://raw.githubusercontent.com/hasaneyldrm/exercises-dataset/main/videos/0042-zG0zs85.gif', TRUE, 'weight_reps'),
  ('ex_barbell_full_squat_back_pov', 'S Velkou činkou (VČ) full Dřep (back pov)', 'Nohy', '{"Kvadricepsy","Hamstringy","Lýtka"}', 'Stand with your feet shoulder-width apart, toes slightly turned out. Hold the barbell across your upper back, resting it on your traps or rear delts. Engage your core and keep your chest up as you begin to lower your body down.', 'https://raw.githubusercontent.com/hasaneyldrm/exercises-dataset/main/videos/1461-DhMl549.gif', TRUE, 'weight_reps'),
  ('ex_barbell_full_squat_side_pov', 'S Velkou činkou (VČ) full Dřep (side pov)', 'Nohy', '{"Kvadricepsy","Hamstringy","Lýtka"}', 'Stand with your feet shoulder-width apart, toes slightly turned out. Hold the barbell across your upper back, resting it on your traps or rear delts. Engage your core and keep your chest up as you begin to lower your body down.', 'https://raw.githubusercontent.com/hasaneyldrm/exercises-dataset/main/videos/1462-iYzB0Cz.gif', TRUE, 'weight_reps'),
  ('ex_barbell_full_zercher_squat', 'Zercher dřep (činka v loktech)', 'Nohy', '{"Kvadricepsy","Hamstringy","Lýtka"}', 'Stand with your feet shoulder-width apart and toes slightly turned out. Hold the barbell in the crooks of your elbows, with your hands gripping the barbell for stability. Engage your core and keep your chest lifted as you lower your hips back and down into a squat position.', 'https://raw.githubusercontent.com/hasaneyldrm/exercises-dataset/main/videos/1545-vR1vold.gif', TRUE, 'weight_reps'),
  ('ex_barbell_glute_bridge', 'S Velkou činkou (VČ) Most na hýždě (Glute bridge)', 'Nohy', '{"Hamstringy","Spodní záda"}', 'Start by lying flat on your back on the ground with your knees bent and feet flat on the floor. Place a barbell across your hips, holding it securely with both hands. Engage your glutes and core muscles, then lift your hips off the ground until your body forms a straight line from your knees to your shoulders.', 'https://raw.githubusercontent.com/hasaneyldrm/exercises-dataset/main/videos/1409-qKBpF7I.gif', TRUE, 'weight_reps'),
  ('ex_barbell_glute_bridge_two_legs_on_bench_male', 'S Velkou činkou (VČ) Most na hýždě (Glute bridge) two legs on bench (male)', 'Nohy', '{"Hamstringy","Střed těla"}', 'Start by sitting on the edge of a bench with your upper back resting against it and your feet flat on the ground, hip-width apart. Place a barbell across your hips, holding it securely with both hands. Engage your glutes and core muscles, then press through your heels to lift your hips off the bench, creating a straight line from your knees to your shoulders.', 'https://raw.githubusercontent.com/hasaneyldrm/exercises-dataset/main/videos/3562-qg2PGl6.gif', TRUE, 'weight_reps'),
  ('ex_barbell_hack_squat', 'Hacken dřep na stroji', 'Nohy', '{"Kvadricepsy","Hamstringy","Lýtka"}', 'Start by standing with your feet shoulder-width apart and your toes slightly turned out. Hold the barbell behind your legs, resting it on your upper thighs. Lower your body by bending at the knees and hips, keeping your back straight and your chest up.', 'https://raw.githubusercontent.com/hasaneyldrm/exercises-dataset/main/videos/0046-5VCj6iH.gif', TRUE, 'weight_reps'),
  ('ex_barbell_high_bar_squat', 'S Velkou činkou (VČ) high bar Dřep', 'Nohy', '{"Kvadricepsy","Hamstringy","Lýtka"}', 'Stand with your feet shoulder-width apart, toes slightly turned out. Place the barbell on your upper back, resting it on your traps. Engage your core and keep your chest up as you begin to squat down, pushing your hips back and bending your knees.', 'https://raw.githubusercontent.com/hasaneyldrm/exercises-dataset/main/videos/1436-Gnfo4FM.gif', TRUE, 'weight_reps'),
  ('ex_barbell_jefferson_squat', 'S Velkou činkou (VČ) jefferson Dřep', 'Nohy', '{"Kvadricepsy","Hamstringy","Lýtka"}', 'Stand with your feet shoulder-width apart and toes slightly turned out. Hold the barbell with an overhand grip, resting it on the front of your body, just below your waist. Step your left foot forward and your right foot back, keeping your feet shoulder-width apart.', 'https://raw.githubusercontent.com/hasaneyldrm/exercises-dataset/main/videos/0051-pkSoCW9.gif', TRUE, 'weight_reps'),
  ('ex_barbell_jump_squat', 'S Velkou činkou (VČ) jump Dřep', 'Nohy', '{"Kvadricepsy","Hamstringy","Lýtka"}', 'Start by standing with your feet shoulder-width apart, holding a barbell across your upper back. Lower your body into a squat position by bending your knees and pushing your hips back. Once you reach the bottom of the squat, explode upwards by jumping off the ground.', 'https://raw.githubusercontent.com/hasaneyldrm/exercises-dataset/main/videos/0053-1gFNTZV.gif', TRUE, 'weight_reps'),
  ('ex_barbell_lateral_lunge', 'S Velkou činkou (VČ) lateral Výpad', 'Nohy', '{"Kvadricepsy","Hamstringy","Lýtka"}', 'Stand with your feet shoulder-width apart, holding a barbell across your upper back. Take a big step to the side with your right foot, keeping your left foot planted. Bend your right knee and lower your body down into a lunge position, keeping your left leg straight.', 'https://raw.githubusercontent.com/hasaneyldrm/exercises-dataset/main/videos/1410-py1HSzx.gif', TRUE, 'weight_reps'),
  ('ex_barbell_low_bar_squat', 'S Velkou činkou (VČ) low bar Dřep', 'Nohy', '{"Kvadricepsy","Hamstringy","Lýtka"}', 'Stand with your feet shoulder-width apart and the barbell resting on your upper back. Keeping your chest up and core engaged, slowly lower your body by bending your knees and pushing your hips back. Continue lowering until your thighs are parallel to the ground or slightly below.', 'https://raw.githubusercontent.com/hasaneyldrm/exercises-dataset/main/videos/1435-bTpEUcm.gif', TRUE, 'weight_reps'),
  ('ex_barbell_lunge', 'S Velkou činkou (VČ) Výpad', 'Nohy', '{"Kvadricepsy","Hamstringy","Lýtka"}', 'Start by standing with your feet shoulder-width apart and a barbell resting on your upper back. Take a step forward with your right foot, keeping your torso upright. Lower your body by bending your right knee until your thigh is parallel to the ground.', 'https://raw.githubusercontent.com/hasaneyldrm/exercises-dataset/main/videos/0054-t8iSghb.gif', TRUE, 'weight_reps'),
  ('ex_barbell_lying_lifting_on_hip', 'S Velkou činkou (VČ) v leže lifting (on hip)', 'Nohy', '{"Hamstringy","Kvadricepsy"}', 'Lie flat on your back on a bench with your feet flat on the ground and your knees bent. Hold the barbell with an overhand grip and position it on your hips. Engaging your glutes, lift your hips off the bench until your body forms a straight line from your knees to your shoulders.', 'https://raw.githubusercontent.com/hasaneyldrm/exercises-dataset/main/videos/0058-SNFfUff.gif', TRUE, 'weight_reps'),
  ('ex_barbell_narrow_stance_squat', 'S Velkou činkou (VČ) narrow stance Dřep', 'Nohy', '{"Kvadricepsy","Hamstringy","Lýtka"}', 'Stand with your feet shoulder-width apart and toes pointing slightly outward. Hold the barbell across your upper back, resting it on your traps or rear delts. Engage your core and keep your chest up as you slowly lower your body by bending your knees and pushing your hips back.', 'https://raw.githubusercontent.com/hasaneyldrm/exercises-dataset/main/videos/0063-elhhVgj.gif', TRUE, 'weight_reps'),
  ('ex_barbell_one_arm_side_deadlift', 'S Velkou činkou (VČ) jednoruč side Mrtvý tah', 'Nohy', '{"Hamstringy","Kvadricepsy","Spodní záda"}', 'Stand with your feet shoulder-width apart, holding a barbell in one hand with an overhand grip. Keep your back straight and your core engaged. Bend at the hips and lower the barbell towards the outside of your leg, keeping your arm straight and your chest up.', 'https://raw.githubusercontent.com/hasaneyldrm/exercises-dataset/main/videos/0066-2DxtqHL.gif', TRUE, 'weight_reps'),
  ('ex_barbell_one_leg_squat', 'S Velkou činkou (VČ) one leg Dřep', 'Nohy', '{"Hýždě","Hamstringy","Lýtka"}', 'Stand with your feet shoulder-width apart and hold a barbell across your upper back. Lift one foot off the ground and extend it forward, keeping it parallel to the ground. Bend your standing leg and lower your body down as if sitting back into a chair, keeping your chest up and your back straight.', 'https://raw.githubusercontent.com/hasaneyldrm/exercises-dataset/main/videos/0068-uKyN64F.gif', TRUE, 'weight_reps'),
  ('ex_barbell_rack_pull', 'S Velkou činkou (VČ) rack pull', 'Nohy', '{"Hamstringy","Spodní záda"}', 'Set up a barbell on a rack at knee height. Stand with your feet shoulder-width apart, toes pointing slightly outwards. Bend at the hips and knees to lower yourself down and grip the barbell with an overhand grip, hands shoulder-width apart.', 'https://raw.githubusercontent.com/hasaneyldrm/exercises-dataset/main/videos/0074-za9Ni4z.gif', TRUE, 'weight_reps'),
  ('ex_barbell_rear_lunge_v_2', 'S Velkou činkou (VČ) rear Výpad v. 2', 'Nohy', '{"Kvadricepsy","Hamstringy","Lýtka"}', 'Stand with your feet shoulder-width apart and hold a barbell across your upper back. Take a step backward with your right foot, landing on the ball of your foot. Bend both knees to lower your body until your left thigh is parallel to the ground.', 'https://raw.githubusercontent.com/hasaneyldrm/exercises-dataset/main/videos/0077-62Nw60O.gif', TRUE, 'weight_reps'),
  ('ex_barbell_seated_calf_raise', 'S Velkou činkou (VČ) v sedě Výpony na lýtka', 'Nohy', '{"Hamstringy"}', 'Sit on a bench with your feet flat on the floor and a barbell resting on your thighs. Place the balls of your feet on a raised platform, such as a block or step. Lower your heels as far as possible, feeling a stretch in your calves.', 'https://raw.githubusercontent.com/hasaneyldrm/exercises-dataset/main/videos/1371-ipvgBnC.gif', TRUE, 'weight_reps'),
  ('ex_barbell_seated_good_morning', 'S Velkou činkou (VČ) v sedě good morning', 'Nohy', '{"Hamstringy","Spodní záda"}', 'Sit on a bench with your feet flat on the ground and a barbell resting on your upper back. Keep your back straight and your chest up. Slowly hinge forward at the hips, lowering your torso towards the ground.', 'https://raw.githubusercontent.com/hasaneyldrm/exercises-dataset/main/videos/0090-d960PgE.gif', TRUE, 'weight_reps'),
  ('ex_barbell_side_split_squat', 'S Velkou činkou (VČ) side split Dřep', 'Nohy', '{"Hýždě","Hamstringy","Lýtka"}', 'Stand with your feet wider than shoulder-width apart, toes pointing slightly outward. Hold a barbell across your upper back, resting it on your traps. Engage your core and keep your chest up as you lower your body down into a squat position, bending at the knees and hips.', 'https://raw.githubusercontent.com/hasaneyldrm/exercises-dataset/main/videos/0098-W31mMjd.gif', TRUE, 'weight_reps'),
  ('ex_barbell_side_split_squat_v_2', 'S Velkou činkou (VČ) side split Dřep v. 2', 'Nohy', '{"Hýždě","Hamstringy","Lýtka"}', 'Stand with your feet wider than shoulder-width apart, toes pointing slightly outwards. Hold a barbell across your upper back, resting it on your shoulders. Take a big step to the side with your right foot, keeping your left foot planted.', 'https://raw.githubusercontent.com/hasaneyldrm/exercises-dataset/main/videos/0097-HUEqZ1y.gif', TRUE, 'weight_reps'),
  ('ex_barbell_single_leg_deadlift', 'S Velkou činkou (VČ) jednonož Mrtvý tah', 'Nohy', '{"Hamstringy","Spodní záda"}', 'Stand with your feet hip-width apart, holding a barbell in front of your thighs with an overhand grip. Shift your weight onto your left foot and lift your right foot slightly off the ground. Hinge forward at the hips, keeping your back straight and your right leg extended behind you for balance.', 'https://raw.githubusercontent.com/hasaneyldrm/exercises-dataset/main/videos/1756-gEyURal.gif', TRUE, 'weight_reps'),
  ('ex_barbell_speed_squat', 'S Velkou činkou (VČ) speed Dřep', 'Nohy', '{"Kvadricepsy","Hamstringy","Lýtka"}', 'Stand with your feet shoulder-width apart, toes slightly turned out. Hold the barbell across your upper back, resting it on your traps or rear delts. Engage your core and keep your chest up as you lower your hips back and down, as if sitting into a chair.', 'https://raw.githubusercontent.com/hasaneyldrm/exercises-dataset/main/videos/0101-euI1BwR.gif', TRUE, 'weight_reps'),
  ('ex_barbell_split_squat_v_2', 'S Velkou činkou (VČ) split Dřep v. 2', 'Nohy', '{"Hýždě","Hamstringy","Lýtka"}', 'Start by standing with your feet shoulder-width apart, holding a barbell across your upper back. Take a large step forward with your right foot, keeping your torso upright. Lower your body by bending your knees and hips until your right thigh is parallel to the ground.', 'https://raw.githubusercontent.com/hasaneyldrm/exercises-dataset/main/videos/2810-HBYyX94.gif', TRUE, 'weight_reps'),
  ('ex_barbell_squat_on_knees', 'S Velkou činkou (VČ) Dřep (on knees)', 'Nohy', '{"Hýždě","Hamstringy","Lýtka"}', 'Start by kneeling on the ground with your knees hip-width apart and your toes pointing forward. Place a barbell across your shoulders, gripping it with an overhand grip and your hands slightly wider than shoulder-width apart. Engage your core and keep your chest lifted as you slowly lower your body down by bending your knees, keeping your back straight.', 'https://raw.githubusercontent.com/hasaneyldrm/exercises-dataset/main/videos/0102-oR7O9LW.gif', TRUE, 'weight_reps'),
  ('ex_barbell_squat_jump_step_rear_lunge', 'S Velkou činkou (VČ) Dřep jump step rear Výpad', 'Nohy', '{"Hýždě","Hamstringy","Lýtka"}', 'Start by standing with your feet shoulder-width apart, holding a barbell across your upper back. Lower your body into a squat position by bending your knees and pushing your hips back. Explode upwards, jumping off the ground as high as you can.', 'https://raw.githubusercontent.com/hasaneyldrm/exercises-dataset/main/videos/2798-RYcV1kH.gif', TRUE, 'weight_reps'),
  ('ex_barbell_standing_leg_calf_raise', 'S Velkou činkou (VČ) ve stoje leg Výpony na lýtka', 'Nohy', '{"Hamstringy","Hýždě"}', 'Stand with your feet shoulder-width apart and place a barbell across your upper back. Raise your heels off the ground as high as possible, using your calves. Pause for a moment at the top, then slowly lower your heels back down to the starting position.', 'https://raw.githubusercontent.com/hasaneyldrm/exercises-dataset/main/videos/0108-rGwhJ5o.gif', TRUE, 'weight_reps'),
  ('ex_barbell_standing_rocking_leg_calf_raise', 'S Velkou činkou (VČ) ve stoje rocking leg Výpony na lýtka', 'Nohy', '{"Hamstringy","Kvadricepsy"}', 'Stand with your feet shoulder-width apart and hold a barbell across your upper back. Raise your heels off the ground as high as possible, balancing on the balls of your feet. Slowly lower your heels back down to the starting position.', 'https://raw.githubusercontent.com/hasaneyldrm/exercises-dataset/main/videos/0111-6HiHHe0.gif', TRUE, 'weight_reps'),
  ('ex_barbell_step_up', 'S Velkou činkou (VČ) Vystupování na bednu (Step-up)', 'Nohy', '{"Kvadricepsy","Hamstringy","Lýtka"}', 'Stand in front of a bench or step with a barbell resting on your upper back. Place one foot on the bench or step, ensuring your entire foot is in contact with the surface. Push through your heel and step up onto the bench or step, fully extending your hip and knee.', 'https://raw.githubusercontent.com/hasaneyldrm/exercises-dataset/main/videos/0114-Kxquu2E.gif', TRUE, 'weight_reps'),
  ('ex_barbell_stiff_leg_good_morning', 'S Velkou činkou (VČ) stiff leg good morning', 'Nohy', '{"Hamstringy","Spodní záda"}', 'Stand with your feet shoulder-width apart and your knees slightly bent. Hold the barbell across your upper back, resting it on your traps. Keeping your back straight, hinge forward at the hips, pushing your glutes back.', 'https://raw.githubusercontent.com/hasaneyldrm/exercises-dataset/main/videos/0115-JrOHAZc.gif', TRUE, 'weight_reps'),
  ('ex_barbell_straight_leg_deadlift', 'S Velkou činkou (VČ) straight leg Mrtvý tah', 'Nohy', '{"Hýždě","Spodní záda"}', 'Stand with your feet shoulder-width apart and your toes pointing forward. Hold the barbell with an overhand grip, hands slightly wider than shoulder-width apart. Bend at your hips and lower the barbell towards the ground, keeping your back straight and your knees slightly bent.', 'https://raw.githubusercontent.com/hasaneyldrm/exercises-dataset/main/videos/0116-hrVQWvE.gif', TRUE, 'weight_reps'),
  ('ex_barbell_sumo_deadlift', 'S Velkou činkou (VČ) sumo Mrtvý tah', 'Nohy', '{"Hamstringy","Kvadricepsy","Spodní záda"}', 'Stand with your feet wider than shoulder-width apart, toes pointing outwards. Place a barbell on the ground in front of you, centered between your feet. Bend your knees and lower your hips, keeping your back straight and chest up, to grip the barbell with an overhand grip.', 'https://raw.githubusercontent.com/hasaneyldrm/exercises-dataset/main/videos/0117-KgI0tqW.gif', TRUE, 'weight_reps'),
  ('ex_barbell_wide_squat', 'S Velkou činkou (VČ) širokým úchopem Dřep', 'Nohy', '{"Hýždě","Hamstringy","Lýtka"}', 'Stand with your feet wider than shoulder-width apart, toes pointing slightly outward. Hold the barbell across your upper back, resting it on your traps or rear delts. Engage your core and keep your chest up as you lower your body down into a squat, pushing your hips back and bending your knees.', 'https://raw.githubusercontent.com/hasaneyldrm/exercises-dataset/main/videos/0124-s7HX1BY.gif', TRUE, 'weight_reps'),
  ('ex_barbell_zercher_squat', 'Zercher dřep (činka v loktech)', 'Nohy', '{"Kvadricepsy","Hamstringy","Lýtka"}', 'Stand with your feet shoulder-width apart and toes slightly turned out. Hold the barbell in the crooks of your elbows, with your hands gripping the bar for stability. Engage your core and keep your chest lifted as you lower your hips back and down into a squat position.', 'https://raw.githubusercontent.com/hasaneyldrm/exercises-dataset/main/videos/0127-LSTChY9.gif', TRUE, 'weight_reps'),
  ('ex_basic_toe_touch_male', 'Basic toe touch (male)', 'Nohy', '{"Hamstringy","Lýtka"}', 'Stand with your feet shoulder-width apart and your arms by your sides. Bend forward at the waist, keeping your back straight and your knees slightly bent. Reach down towards your toes with your hands, keeping your legs as straight as possible.', 'https://raw.githubusercontent.com/hasaneyldrm/exercises-dataset/main/videos/3212-BbfB8Gb.gif', TRUE, 'reps_only'),
  ('ex_bench_hip_extension', 'Bench hip Extenze', 'Nohy', '{"Hamstringy"}', 'Sit on a bench with your back against the bench and your feet flat on the ground. Place your hands on the bench for support. Engage your glutes and hamstrings, then lift your hips off the bench until your body forms a straight line from your knees to your shoulders.', 'https://raw.githubusercontent.com/hasaneyldrm/exercises-dataset/main/videos/0130-u27Kcdz.gif', TRUE, 'reps_only'),
  ('ex_assisted_triceps_dip_kneeling', 'Assisted triceps Kliky na bradlech (v kleče)', 'Ruce', '{"Hrudník","Ramena"}', 'Adjust the machine to your desired weight and height. Kneel down on the pad facing the machine, with your hands gripping the handles. Lower your body by bending your elbows, keeping your back straight and close to the machine.', 'https://raw.githubusercontent.com/hasaneyldrm/exercises-dataset/main/videos/0019-J60bN17.gif', TRUE, 'weight_reps'),
  ('ex_barbell_alternate_biceps_curl', 'S Velkou činkou (VČ) alternate biceps Bicepsový zdvih', 'Ruce', '{"Předloktí"}', 'Stand up straight with your feet shoulder-width apart and hold a barbell in each hand, palms facing forward. Keep your upper arms stationary and exhale as you curl the weights while contracting your biceps. Continue to raise the barbells until your biceps are fully contracted and the barbells are at shoulder level.', 'https://raw.githubusercontent.com/hasaneyldrm/exercises-dataset/main/videos/0023-Yza7XrQ.gif', TRUE, 'weight_reps'),
  ('ex_barbell_biceps_curl_with_arm_blaster', 'S Velkou činkou (VČ) biceps Bicepsový zdvih (with arm blaster)', 'Ruce', '{"Předloktí"}', 'Stand up straight with your feet shoulder-width apart and hold a barbell with an underhand grip, palms facing up. Place your upper arms against the arm blaster, keeping your elbows close to your torso. Keeping your upper arms stationary, exhale and curl the weights while contracting your biceps.', 'https://raw.githubusercontent.com/hasaneyldrm/exercises-dataset/main/videos/2407-aee2Fcj.gif', TRUE, 'weight_reps'),
  ('ex_barbell_decline_close_grip_to_skull_press', 'S Velkou činkou (VČ) hlavou dolů úzkým úchopem to skull Tlaky', 'Ruce', '{"Hrudník","Ramena"}', 'Lie on a decline bench with your head lower than your feet and hold a barbell with a close grip. Lower the barbell towards your forehead by bending your elbows, keeping your upper arms stationary. Pause for a moment, then extend your arms to press the barbell back up to the starting position.', 'https://raw.githubusercontent.com/hasaneyldrm/exercises-dataset/main/videos/0035-LMGXZn8.gif', TRUE, 'weight_reps'),
  ('ex_barbell_drag_curl', 'S Velkou činkou (VČ) drag Bicepsový zdvih', 'Ruce', '{"Předloktí"}', 'Stand with your feet shoulder-width apart and hold a barbell with an underhand grip, palms facing up. Let the barbell hang at arm''s length in front of your thighs. Keeping your upper arms stationary, curl the barbell up towards your chest by contracting your biceps.', 'https://raw.githubusercontent.com/hasaneyldrm/exercises-dataset/main/videos/0038-IENzBdA.gif', TRUE, 'weight_reps'),
  ('ex_barbell_incline_close_grip_bench_press', 'S Velkou činkou (VČ) šikmo nahoru úzkým úchopem Bench Press', 'Ruce', '{"Hrudník","Ramena"}', 'Set up an incline bench at a 45-degree angle. Lie down on the bench with your feet flat on the ground. Grasp the barbell with a close grip, slightly narrower than shoulder-width apart.', 'https://raw.githubusercontent.com/hasaneyldrm/exercises-dataset/main/videos/1719-gx7s7uF.gif', TRUE, 'weight_reps'),
  ('ex_barbell_incline_reverse_grip_press', 'S Velkou činkou (VČ) šikmo nahoru reverse-grip Tlaky', 'Ruce', '{"Hrudník","Ramena"}', 'Set up an incline bench at a 45-degree angle. Lie back on the bench and grasp the barbell with a reverse grip, hands slightly wider than shoulder-width apart. Unrack the barbell and lower it towards your upper chest, keeping your elbows tucked in.', 'https://raw.githubusercontent.com/hasaneyldrm/exercises-dataset/main/videos/0048-641mIfk.gif', TRUE, 'weight_reps'),
  ('ex_barbell_jm_bench_press', 'S Velkou činkou (VČ) jm Bench Press', 'Ruce', '{"Hrudník","Ramena"}', 'Lie flat on a bench with your feet flat on the ground and your back pressed against the bench. Grasp the barbell with an overhand grip, slightly wider than shoulder-width apart. Lower the barbell to your chest, keeping your elbows tucked in close to your body.', 'https://raw.githubusercontent.com/hasaneyldrm/exercises-dataset/main/videos/0052-ZsiqXYa.gif', TRUE, 'weight_reps'),
  ('ex_barbell_lying_back_of_the_head_tricep_extension', 'S Velkou činkou (VČ) v leže back of the head tricep Extenze', 'Ruce', '{"Ramena"}', 'Lie flat on a bench with your feet flat on the ground and your head at the end of the bench. Hold a barbell with an overhand grip, hands shoulder-width apart, and extend your arms straight up over your chest. Keeping your upper arms stationary, slowly lower the barbell behind your head by bending your elbows.', 'https://raw.githubusercontent.com/hasaneyldrm/exercises-dataset/main/videos/1720-yg8Totb.gif', TRUE, 'weight_reps'),
  ('ex_barbell_lying_close_grip_press', 'S Velkou činkou (VČ) v leže úzkým úchopem Tlaky', 'Ruce', '{"Hrudník","Ramena"}', 'Lie flat on a bench with your feet flat on the ground and your back pressed against the bench. Grasp the barbell with a close grip, hands shoulder-width apart, palms facing towards your feet. Lift the barbell off the rack and hold it directly above your chest with your arms fully extended.', 'https://raw.githubusercontent.com/hasaneyldrm/exercises-dataset/main/videos/0055-EcaV7aL.gif', TRUE, 'weight_reps'),
  ('ex_barbell_lying_close_grip_triceps_extension', 'S Velkou činkou (VČ) v leže úzkým úchopem Tricepsové extenze', 'Ruce', '{"Ramena"}', 'Lie flat on a bench with your feet flat on the ground and your head at the end of the bench. Grasp the barbell with a close grip, hands shoulder-width apart, palms facing up. Extend your arms fully, lifting the barbell above your chest.', 'https://raw.githubusercontent.com/hasaneyldrm/exercises-dataset/main/videos/0056-HJ63mSO.gif', TRUE, 'weight_reps'),
  ('ex_barbell_lying_extension', 'S Velkou činkou (VČ) v leže Extenze', 'Ruce', '{"Ramena"}', 'Lie flat on a bench with your feet flat on the ground and your head at the end of the bench. Hold the barbell with an overhand grip, hands shoulder-width apart, and extend your arms straight up over your chest. Keeping your upper arms stationary, slowly lower the barbell towards your forehead by bending your elbows.', 'https://raw.githubusercontent.com/hasaneyldrm/exercises-dataset/main/videos/0057-EMpUwRI.gif', TRUE, 'weight_reps'),
  ('ex_barbell_lying_preacher_curl', 'S Velkou činkou (VČ) v leže preacher Bicepsový zdvih', 'Ruce', '{"Předloktí"}', 'Sit on a preacher bench with your chest against the pad and your arms extended over the edge, holding a barbell with an underhand grip. Keeping your upper arms stationary, exhale and curl the weights while contracting your biceps. Continue to raise the bar until your biceps are fully contracted and the bar is at shoulder level.', 'https://raw.githubusercontent.com/hasaneyldrm/exercises-dataset/main/videos/0059-SYJ4Bkt.gif', TRUE, 'weight_reps'),
  ('ex_barbell_lying_triceps_extension', 'S Velkou činkou (VČ) v leže Tricepsové extenze', 'Ruce', '{"Ramena"}', 'Lie flat on a bench with your feet flat on the ground and your head at the end of the bench. Hold the barbell with an overhand grip, hands shoulder-width apart, and extend your arms straight up over your chest. Keeping your upper arms stationary, slowly lower the barbell towards your forehead by bending your elbows.', 'https://raw.githubusercontent.com/hasaneyldrm/exercises-dataset/main/videos/0061-iZop9xO.gif', TRUE, 'weight_reps'),
  ('ex_barbell_one_arm_floor_press', 'S Velkou činkou (VČ) jednoruč floor Tlaky', 'Ruce', '{"Hrudník","Ramena"}', 'Lie flat on your back on the floor with your knees bent and feet flat on the ground. Hold the barbell with one hand, palm facing up, and extend your arm straight up over your chest. Slowly lower the barbell towards your chest, keeping your elbow close to your body.', 'https://raw.githubusercontent.com/hasaneyldrm/exercises-dataset/main/videos/0065-vtusOWT.gif', TRUE, 'weight_reps'),
  ('ex_barbell_palms_down_wrist_curl_over_a_bench', 'S Velkou činkou (VČ) palms down wrist Bicepsový zdvih over a bench', 'Ruce', '{"Biceps","Hluboký sval pažní"}', 'Sit on a bench with your feet flat on the ground and your forearms resting on your thighs, palms facing down. Hold a barbell with an overhand grip, hands shoulder-width apart. Lower the barbell towards the ground by flexing your wrists, keeping your forearms stationary.', 'https://raw.githubusercontent.com/hasaneyldrm/exercises-dataset/main/videos/1411-yzYH9pI.gif', TRUE, 'weight_reps'),
  ('ex_barbell_palms_up_wrist_curl_over_a_bench', 'S Velkou činkou (VČ) palms up wrist Bicepsový zdvih over a bench', 'Ruce', '{"Biceps","Ramena"}', 'Sit on a bench with your feet flat on the ground and hold a barbell with an underhand grip, palms facing up. Rest your forearms on the bench, allowing your wrists to hang off the edge. Keeping your forearms stationary, exhale and curl your wrists upwards as far as possible.', 'https://raw.githubusercontent.com/hasaneyldrm/exercises-dataset/main/videos/1412-SJAA2IQ.gif', TRUE, 'weight_reps'),
  ('ex_barbell_pin_presses', 'S Velkou činkou (VČ) pin Tlaky', 'Ruce', '{"Ramena"}', 'Set up a barbell on a power rack at chest height. Stand facing the barbell and position yourself underneath it, with your feet shoulder-width apart. Grip the barbell with an overhand grip, slightly wider than shoulder-width apart.', 'https://raw.githubusercontent.com/hasaneyldrm/exercises-dataset/main/videos/1751-bndCa3Q.gif', TRUE, 'weight_reps'),
  ('ex_barbell_preacher_curl', 'S Velkou činkou (VČ) preacher Bicepsový zdvih', 'Ruce', '{"Předloktí"}', 'Sit on a preacher bench with your upper arms resting on the pad and your chest against the support. Grasp the barbell with an underhand grip, slightly wider than shoulder-width apart. Keeping your upper arms stationary, exhale and curl the barbell up towards your shoulders.', 'https://raw.githubusercontent.com/hasaneyldrm/exercises-dataset/main/videos/0070-qOgPVf6.gif', TRUE, 'weight_reps'),
  ('ex_barbell_prone_incline_curl', 'S Velkou činkou (VČ) prone šikmo nahoru Bicepsový zdvih', 'Ruce', '{"Předloktí"}', 'Set up an incline bench at a 45-degree angle. Lie face down on the bench with your chest and stomach resting against it. Hold a barbell with an underhand grip, shoulder-width apart.', 'https://raw.githubusercontent.com/hasaneyldrm/exercises-dataset/main/videos/0072-WLvTAv5.gif', TRUE, 'weight_reps'),
  ('ex_barbell_revers_wrist_curl_v_2', 'S Velkou činkou (VČ) revers wrist Bicepsový zdvih v. 2', 'Ruce', '{"Biceps","Hluboký sval pažní"}', 'Sit on a bench with your feet flat on the ground and your knees bent. Hold a barbell with an overhand grip, palms facing down, and your hands shoulder-width apart. Rest your forearms on your thighs, allowing your wrists to hang off the edge.', 'https://raw.githubusercontent.com/hasaneyldrm/exercises-dataset/main/videos/0079-qDnGfDb.gif', TRUE, 'weight_reps'),
  ('ex_barbell_reverse_close_grip_bench_press', 'S Velkou činkou (VČ) reverse úzkým úchopem Bench Press', 'Ruce', '{"Hrudník","Ramena"}', 'Lie flat on a bench with your feet flat on the ground and your back pressed against the bench. Grasp the barbell with a reverse grip, hands shoulder-width apart. Lift the barbell off the rack and hold it directly above your chest with your arms fully extended.', 'https://raw.githubusercontent.com/hasaneyldrm/exercises-dataset/main/videos/2187-YqJw82s.gif', TRUE, 'weight_reps'),
  ('ex_barbell_reverse_grip_skullcrusher', 'S Velkou činkou (VČ) podhmatem skullcrusher', 'Ruce', '{"Předloktí"}', 'Lie flat on a bench with your feet flat on the ground and your head at the end of the bench. Hold the barbell with a reverse grip, palms facing towards your face, and your hands shoulder-width apart. Extend your arms straight up over your chest, keeping your elbows in and your wrists straight.', 'https://raw.githubusercontent.com/hasaneyldrm/exercises-dataset/main/videos/1721-yRLPCLu.gif', TRUE, 'weight_reps'),
  ('ex_barbell_reverse_preacher_curl', 'S Velkou činkou (VČ) reverse preacher Bicepsový zdvih', 'Ruce', '{"Předloktí"}', 'Sit on a preacher bench with your chest against the pad and your arms extended straight down, holding a barbell with an overhand grip. Keeping your upper arms stationary, exhale and curl the barbell upward while contracting your biceps. Continue to raise the barbell until your biceps are fully contracted and the barbell is at shoulder level.', 'https://raw.githubusercontent.com/hasaneyldrm/exercises-dataset/main/videos/0081-4LIG9xr.gif', TRUE, 'weight_reps'),
  ('ex_barbell_reverse_wrist_curl', 'S Velkou činkou (VČ) reverse wrist Bicepsový zdvih', 'Ruce', '{"Biceps","Hluboký sval pažní"}', 'Sit on a bench with your feet flat on the ground and hold a barbell with an overhand grip, palms facing down. Rest your forearms on your thighs, allowing your wrists to hang off the edge. Slowly curl your wrists upward, bringing the barbell towards your body.', 'https://raw.githubusercontent.com/hasaneyldrm/exercises-dataset/main/videos/0082-LsZkfU6.gif', TRUE, 'weight_reps'),
  ('ex_barbell_seated_close_grip_behind_neck_triceps_extension', 'S Velkou činkou (VČ) v sedě úzkým úchopem behind neck Tricepsové extenze', 'Ruce', '{"Ramena"}', 'Sit on a bench with your back straight and feet flat on the ground. Hold the barbell with a close grip behind your neck, palms facing forward. Keep your elbows close to your head and slowly lower the barbell towards the back of your head.', 'https://raw.githubusercontent.com/hasaneyldrm/exercises-dataset/main/videos/1718-4CBIBOM.gif', TRUE, 'weight_reps'),
  ('ex_barbell_seated_close_grip_concentration_curl', 'S Velkou činkou (VČ) v sedě úzkým úchopem concentration Bicepsový zdvih', 'Ruce', '{"Předloktí"}', 'Sit on a bench with your feet flat on the floor and hold a barbell with an underhand grip, hands shoulder-width apart. Rest your upper arms against your inner thighs, just above your knees, and let the barbell hang down in front of you. Keeping your upper arms stationary, exhale and curl the barbell up towards your shoulders, contracting your biceps.', 'https://raw.githubusercontent.com/hasaneyldrm/exercises-dataset/main/videos/0089-1V1gj1u.gif', TRUE, 'weight_reps'),
  ('ex_barbell_seated_overhead_triceps_extension', 'S Velkou činkou (VČ) v sedě overhead Tricepsové extenze', 'Ruce', '{"Ramena"}', 'Sit on a bench with your back straight and feet flat on the ground. Hold a barbell with an overhand grip, hands shoulder-width apart, and raise it overhead. Lower the barbell behind your head by bending your elbows, keeping your upper arms close to your head.', 'https://raw.githubusercontent.com/hasaneyldrm/exercises-dataset/main/videos/0092-5uFK1xr.gif', TRUE, 'weight_reps'),
  ('ex_barbell_standing_back_wrist_curl', 'S Velkou činkou (VČ) ve stoje back wrist Bicepsový zdvih', 'Ruce', '{"Biceps","Ramena"}', 'Stand up straight with your feet shoulder-width apart and hold a barbell with an overhand grip. Rest the barbell on the back of your hands with your palms facing down and your fingers pointing towards your body. Keeping your upper arms stationary, exhale and curl your wrists upwards as far as possible.', 'https://raw.githubusercontent.com/hasaneyldrm/exercises-dataset/main/videos/0104-2qTvJAZ.gif', TRUE, 'weight_reps'),
  ('ex_barbell_standing_close_grip_curl', 'S Velkou činkou (VČ) ve stoje úzkým úchopem Bicepsový zdvih', 'Ruce', '{"Předloktí"}', 'Stand up straight with your feet shoulder-width apart and hold a barbell with an underhand grip, hands close together. Keep your elbows close to your torso and your upper arms stationary throughout the movement. Exhale as you curl the weights while contracting your biceps. Continue to raise the bar until your biceps are fully contracted and the bar is at shoulder level.', 'https://raw.githubusercontent.com/hasaneyldrm/exercises-dataset/main/videos/0106-4dUn2iv.gif', TRUE, 'weight_reps'),
  ('ex_barbell_standing_concentration_curl', 'S Velkou činkou (VČ) ve stoje concentration Bicepsový zdvih', 'Ruce', '{"Předloktí"}', 'Stand with your feet shoulder-width apart and hold a barbell in one hand, palm facing up. Rest your opposite hand on your thigh for support. Keeping your upper arm stationary, exhale and curl the weight up towards your shoulder.', 'https://raw.githubusercontent.com/hasaneyldrm/exercises-dataset/main/videos/2414-vsMcDi9.gif', TRUE, 'weight_reps'),
  ('ex_barbell_standing_overhead_triceps_extension', 'S Velkou činkou (VČ) ve stoje overhead Tricepsové extenze', 'Ruce', '{"Ramena"}', 'Stand with your feet shoulder-width apart and hold a barbell with an overhand grip. Raise the barbell overhead, fully extending your arms. Keeping your upper arms close to your head, slowly lower the barbell behind your head by bending your elbows.', 'https://raw.githubusercontent.com/hasaneyldrm/exercises-dataset/main/videos/0109-dZl9Q27.gif', TRUE, 'weight_reps'),
  ('ex_barbell_standing_reverse_grip_curl', 'S Velkou činkou (VČ) ve stoje podhmatem Bicepsový zdvih', 'Ruce', '{"Předloktí"}', 'Stand up straight with your feet shoulder-width apart and hold a barbell with an underhand grip, palms facing up. Keep your elbows close to your torso and your upper arms stationary. Exhale and curl the weights while contracting your biceps, bringing the barbell as close to your shoulders as possible.', 'https://raw.githubusercontent.com/hasaneyldrm/exercises-dataset/main/videos/0110-LWuA3aZ.gif', TRUE, 'weight_reps'),
  ('ex_barbell_standing_wide_grip_biceps_curl', 'S Velkou činkou (VČ) ve stoje širokým úchopem biceps Bicepsový zdvih', 'Ruce', '{"Předloktí"}', 'Stand with your feet shoulder-width apart and hold a barbell with an underhand grip, hands wider than shoulder-width apart. Keep your back straight and your elbows close to your torso. Exhale and curl the barbell up towards your shoulders, keeping your upper arms stationary.', 'https://raw.githubusercontent.com/hasaneyldrm/exercises-dataset/main/videos/1629-faHKVkK.gif', TRUE, 'weight_reps'),
  ('ex_barbell_standing_wide_grip_curl', 'S Velkou činkou (VČ) ve stoje širokým úchopem Bicepsový zdvih', 'Ruce', '{"Předloktí","Ramena"}', 'Stand up straight with your feet shoulder-width apart and hold a barbell with an overhand grip, hands wider than shoulder-width apart. Let the barbell hang at arm''s length in front of your thighs, with your palms facing away from your body. Keeping your upper arms stationary, exhale and curl the barbell upward by contracting your biceps.', 'https://raw.githubusercontent.com/hasaneyldrm/exercises-dataset/main/videos/0113-NdIb5Z1.gif', TRUE, 'weight_reps'),
  ('ex_barbell_wrist_curl', 'S Velkou činkou (VČ) wrist Bicepsový zdvih', 'Ruce', '{"Biceps","Hluboký sval pažní"}', 'Sit on a bench with your feet flat on the ground and your forearms resting on your thighs, holding a barbell with an underhand grip. Allow the barbell to roll down to your fingertips, keeping your wrists straight. Slowly curl the barbell up towards your forearms by flexing your wrists.', 'https://raw.githubusercontent.com/hasaneyldrm/exercises-dataset/main/videos/0126-82LxxkW.gif', TRUE, 'weight_reps'),
  ('ex_bench_dip_knees_bent', 'Bench Kliky na bradlech (knees bent)', 'Ruce', '{"Hrudník","Ramena"}', 'Sit on the edge of a bench or chair with your hands gripping the edge next to your hips. Slide your butt off the bench and straighten your legs in front of you, keeping your heels on the ground. Bend your elbows and lower your body towards the ground, keeping your back close to the bench.', 'https://raw.githubusercontent.com/hasaneyldrm/exercises-dataset/main/videos/0129-RrLske5.gif', TRUE, 'reps_only'),
  ('ex_bench_dip_on_floor', 'Bench Kliky na bradlech on floor', 'Ruce', '{"Hrudník","Ramena"}', 'Sit on the edge of a bench or chair with your hands gripping the edge, fingers pointing forward. Slide your butt off the bench, supporting your weight with your hands. Lower your body by bending your elbows until your upper arms are parallel to the floor.', 'https://raw.githubusercontent.com/hasaneyldrm/exercises-dataset/main/videos/1399-9RT8oQW.gif', TRUE, 'reps_only'),
  ('ex_biceps_leg_concentration_curl', 'Biceps leg concentration Bicepsový zdvih', 'Ruce', '{"Předloktí"}', 'Sit on a bench with your legs spread apart and your feet flat on the ground. Hold a dumbbell in one hand and place your elbow on the inside of your thigh, just above the knee. With your palm facing up, curl the dumbbell towards your shoulder while keeping your upper arm stationary.', 'https://raw.githubusercontent.com/hasaneyldrm/exercises-dataset/main/videos/1770-sJFIDIp.gif', TRUE, 'reps_only'),
  ('ex_biceps_pull_up', 'Biceps Shyby', 'Ruce', '{"Předloktí","Ramena"}', 'Hang from a pull-up bar with your palms facing away from you and your hands shoulder-width apart. Engage your core and pull yourself up by bending your elbows, bringing your chest towards the bar. Pause at the top of the movement, then slowly lower yourself back down to the starting position.', 'https://raw.githubusercontent.com/hasaneyldrm/exercises-dataset/main/videos/0140-guT8YnS.gif', TRUE, 'reps_only'),
  ('ex_body_up', 'Body-up', 'Ruce', '{"Hrudník","Ramena"}', 'Start by placing your hands on a raised surface, such as a bench or parallel bars, with your palms facing down and fingers pointing forward. Extend your legs out in front of you, keeping your heels on the ground and your body straight. Lower your body by bending your elbows, keeping them close to your sides, until your upper arms are parallel to the ground.', 'https://raw.githubusercontent.com/hasaneyldrm/exercises-dataset/main/videos/0137-U6G2gk9.gif', TRUE, 'reps_only'),
  ('ex_bodyweight_kneeling_triceps_extension', 'Bodyweight v kleče Tricepsové extenze', 'Ruce', '{"Ramena","Hrudník"}', 'Kneel down on the ground with your knees hip-width apart. Place your hands on the ground in front of you, shoulder-width apart, fingers pointing forward. Extend your legs straight behind you, balancing on your toes and hands, forming a straight line from head to heels.', 'https://raw.githubusercontent.com/hasaneyldrm/exercises-dataset/main/videos/1771-s0HKO2I.gif', TRUE, 'reps_only'),
  ('ex_bodyweight_side_lying_biceps_curl', 'Bodyweight side v leže biceps Bicepsový zdvih', 'Ruce', '{"Předloktí"}', 'Lie on your side with your legs extended and your head supported by your arm. Hold your upper arm against your side and bend your elbow to curl your forearm towards your shoulder. Pause for a moment at the top, then slowly lower your forearm back down to the starting position.', 'https://raw.githubusercontent.com/hasaneyldrm/exercises-dataset/main/videos/1769-gscGLOU.gif', TRUE, 'reps_only'),
  ('ex_cable_alternate_triceps_extension', 'Na kladce alternate Tricepsové extenze', 'Ruce', '{"Ramena"}', 'Stand facing the cable machine with your feet shoulder-width apart. Hold the cable handle with your right hand and bring your arm up so that your upper arm is parallel to the ground and your elbow is bent at a 90-degree angle. Keep your upper arm stationary and extend your forearm backward, fully straightening your arm.', 'https://raw.githubusercontent.com/hasaneyldrm/exercises-dataset/main/videos/0149-Gchi5Tr.gif', TRUE, 'weight_reps'),
  ('ex_cable_close_grip_curl', 'Na kladce úzkým úchopem Bicepsový zdvih', 'Ruce', '{"Předloktí"}', 'Attach a straight bar to a low pulley cable machine. Stand facing the machine with your feet shoulder-width apart and your knees slightly bent. Grasp the bar with an underhand grip, hands shoulder-width apart.', 'https://raw.githubusercontent.com/hasaneyldrm/exercises-dataset/main/videos/1630-BCGQ6J5.gif', TRUE, 'weight_reps'),
  ('ex_cable_concentration_curl', 'Na kladce concentration Bicepsový zdvih', 'Ruce', '{"Předloktí"}', 'Sit on a bench or chair with your feet flat on the floor and your knees slightly bent. Hold the cable handle with an underhand grip and rest your elbow against the inside of your thigh. Keeping your upper arm stationary, exhale and curl the cable handle towards your shoulder while contracting your biceps.', 'https://raw.githubusercontent.com/hasaneyldrm/exercises-dataset/main/videos/1631-NvfE43H.gif', TRUE, 'weight_reps'),
  ('ex_cable_concentration_extension_on_knee', 'Na kladce concentration Extenze (on knee)', 'Ruce', '{"Předloktí"}', 'Sit on a bench or chair with your knees bent and feet flat on the ground. Hold the cable handle with your right hand and place your elbow on the inside of your right knee. Extend your arm fully, keeping your elbow stationary and close to your knee.', 'https://raw.githubusercontent.com/hasaneyldrm/exercises-dataset/main/videos/0152-Db7eEgw.gif', TRUE, 'weight_reps'),
  ('ex_cable_curl', 'Na kladce Bicepsový zdvih', 'Ruce', '{"Předloktí"}', 'Stand facing the cable machine with your feet shoulder-width apart. Grasp the cable attachment with an underhand grip, palms facing up. Keep your elbows close to your sides and your upper arms stationary.', 'https://raw.githubusercontent.com/hasaneyldrm/exercises-dataset/main/videos/0868-G08RZcQ.gif', TRUE, 'weight_reps'),
  ('ex_3_4_sit_up', '3/4 sit-up', 'Břicho', '{"Ohybače kyčlí","Spodní záda"}', 'Lie flat on your back with your knees bent and feet flat on the ground. Place your hands behind your head with your elbows pointing outwards. Engaging your abs, slowly lift your upper body off the ground, curling forward until your torso is at a 45-degree angle.', 'https://raw.githubusercontent.com/hasaneyldrm/exercises-dataset/main/videos/0001-2gPfomN.gif', TRUE, 'reps_only'),
  ('ex_45_side_bend', '45° side bend', 'Břicho', '{"obliques"}', 'Stand with your feet shoulder-width apart and your arms extended straight down by your sides. Keeping your back straight and your core engaged, slowly bend your torso to one side, lowering your hand towards your knee. Pause for a moment at the bottom, then slowly return to the starting position.', 'https://raw.githubusercontent.com/hasaneyldrm/exercises-dataset/main/videos/0002-Hy9D21L.gif', TRUE, 'reps_only'),
  ('ex_alternate_heel_touchers', 'Alternate heel touchers', 'Břicho', '{"obliques"}', 'Lie flat on your back with your knees bent and feet flat on the ground. Extend your arms straight out to the sides, parallel to the ground. Engaging your abs, lift your shoulders off the ground and reach your right hand towards your right heel.', 'https://raw.githubusercontent.com/hasaneyldrm/exercises-dataset/main/videos/0006-qaZVsGk.gif', TRUE, 'reps_only'),
  ('ex_arm_slingers_hanging_bent_knee_legs', 'Arm slingers hanging bent knee legs', 'Břicho', '{"Ramena","back"}', 'Hang from a pull-up bar with your arms fully extended and your knees bent at a 90-degree angle. Engage your core and lift your knees towards your chest, bringing them as close to your elbows as possible. Slowly lower your legs back down to the starting position.', 'https://raw.githubusercontent.com/hasaneyldrm/exercises-dataset/main/videos/2355-uWpxD4v.gif', TRUE, 'reps_only'),
  ('ex_arm_slingers_hanging_straight_legs', 'Arm slingers hanging straight legs', 'Břicho', '{"Ramena","back"}', 'Hang from a pull-up bar with your arms fully extended and your legs straight down. Engage your core and lift your legs up in front of you until they are parallel to the ground. Hold for a moment at the top, then slowly lower your legs back down to the starting position.', 'https://raw.githubusercontent.com/hasaneyldrm/exercises-dataset/main/videos/2333-PXTIwgu.gif', TRUE, 'reps_only'),
  ('ex_arms_overhead_full_sit_up_male', 'Arms overhead full sit-up (male)', 'Břicho', '{"Ohybače kyčlí","Spodní záda"}', 'Lie flat on your back with your knees bent and feet flat on the ground. Extend your arms overhead, keeping them straight. Engaging your abs, slowly lift your upper body off the ground, curling forward until your torso is upright.', 'https://raw.githubusercontent.com/hasaneyldrm/exercises-dataset/main/videos/3204-NAkmgdx.gif', TRUE, 'reps_only'),
  ('ex_barbell_press_sit_up', 'S Velkou činkou (VČ) Tlaky sit-up', 'Břicho', '{"Ramena","Hrudník"}', 'Lie flat on your back on a mat with your knees bent and feet flat on the ground. Hold the barbell with an overhand grip, resting it on your chest. Engaging your abs, slowly lift your upper body off the ground, curling forward until your torso is at a 45-degree angle.', 'https://raw.githubusercontent.com/hasaneyldrm/exercises-dataset/main/videos/0071-wnEscH8.gif', TRUE, 'weight_reps'),
  ('ex_barbell_seated_twist', 'S Velkou činkou (VČ) v sedě twist', 'Břicho', '{"obliques","Spodní záda"}', 'Sit on a flat bench with your feet flat on the ground and your knees bent. Hold a barbell with both hands in front of your chest, keeping your elbows slightly bent. Engage your core and slowly twist your torso to one side, keeping your back straight.', 'https://raw.githubusercontent.com/hasaneyldrm/exercises-dataset/main/videos/0094-dFSNDOA.gif', TRUE, 'weight_reps'),
  ('ex_barbell_side_bent_v_2', 'S Velkou činkou (VČ) side bent v. 2', 'Břicho', '{"obliques","Spodní záda"}', 'Stand with your feet shoulder-width apart and hold a barbell with both hands, palms facing down. Keep your back straight and core engaged throughout the exercise. Slowly bend your torso to the right side, lowering the barbell towards your right knee.', 'https://raw.githubusercontent.com/hasaneyldrm/exercises-dataset/main/videos/0096-i4JkUaL.gif', TRUE, 'weight_reps'),
  ('ex_barbell_sitted_alternate_leg_raise', 'S Velkou činkou (VČ) sitted alternate Zvedání nohou', 'Břicho', '{"Ohybače kyčlí"}', 'Sit on a bench with your back straight and hold a barbell across your thighs. Keeping your legs straight, lift one leg up as high as possible while keeping the other leg on the ground. Lower the raised leg back down and repeat with the other leg.', 'https://raw.githubusercontent.com/hasaneyldrm/exercises-dataset/main/videos/2799-G7xoEzr.gif', TRUE, 'weight_reps'),
  ('ex_barbell_sitted_alternate_leg_raise_female', 'S Velkou činkou (VČ) sitted alternate Zvedání nohou (female)', 'Břicho', '{"Ohybače kyčlí","Kvadricepsy"}', 'Sit on a bench with your back straight and hold a barbell across your thighs. Place your hands on the sides of the bench for support. Keeping your legs straight, lift one leg up as high as possible while keeping it parallel to the ground.', 'https://raw.githubusercontent.com/hasaneyldrm/exercises-dataset/main/videos/2800-BCs0G2F.gif', TRUE, 'weight_reps'),
  ('ex_barbell_standing_twist', 'S Velkou činkou (VČ) ve stoje twist', 'Břicho', '{"obliques","Spodní záda"}', 'Stand with your feet shoulder-width apart and hold a barbell in front of your chest with both hands, palms facing down. Engage your core and keep your back straight throughout the exercise. Slowly twist your torso to the right, pivoting on your feet and hips, while keeping your lower body stable.', 'https://raw.githubusercontent.com/hasaneyldrm/exercises-dataset/main/videos/0112-yQe5HpE.gif', TRUE, 'weight_reps'),
  ('ex_bottoms_up', 'Bottoms-up', 'Břicho', '{"obliques","Ohybače kyčlí"}', 'Lie flat on your back with your legs extended and your arms by your sides. Bend your knees and bring them towards your chest, keeping your feet off the ground. Engaging your abs, lift your hips off the ground, bringing your knees towards your head.', 'https://raw.githubusercontent.com/hasaneyldrm/exercises-dataset/main/videos/0138-CI6baTY.gif', TRUE, 'reps_only'),
  ('ex_bridge_mountain_climber_cross_body', 'Horolezec na podložce', 'Břicho', '{"Hýždě","Kvadricepsy","Hamstringy"}', 'Start in a high plank position with your hands directly under your shoulders and your body in a straight line. Engage your core and lift your right foot off the ground, bringing your right knee towards your left elbow. Return your right foot to the starting position and repeat the movement with your left foot towards your right elbow.', 'https://raw.githubusercontent.com/hasaneyldrm/exercises-dataset/main/videos/2466-9c6T1YX.gif', TRUE, 'reps_only'),
  ('ex_butt_ups', 'Butt-ups', 'Břicho', '{"Ohybače kyčlí","Spodní záda"}', 'Lie flat on your back with your knees bent and feet flat on the ground. Place your hands by your sides, palms facing down. Engaging your abs, lift your legs off the ground, bringing your knees towards your chest.', 'https://raw.githubusercontent.com/hasaneyldrm/exercises-dataset/main/videos/0870-qcNN2FN.gif', TRUE, 'reps_only'),
  ('ex_cable_judo_flip', 'Na kladce judo flip', 'Břicho', '{"obliques","Ramena"}', 'Stand facing the cable machine with your feet shoulder-width apart. Hold the cable handle with both hands at chest level, palms facing down. Engage your core and rotate your torso to the right, pulling the cable across your body.', 'https://raw.githubusercontent.com/hasaneyldrm/exercises-dataset/main/videos/0174-MvQPqVW.gif', TRUE, 'weight_reps'),
  ('ex_cable_reverse_crunch', 'Na kladce reverse Zkracovačky na břicho', 'Břicho', '{"Ohybače kyčlí"}', 'Attach a cable to a low pulley and lie down facing up on a mat. Hold the cable with both hands and extend your arms straight up towards the ceiling. Bend your knees and lift your legs up, bringing your thighs towards your chest.', 'https://raw.githubusercontent.com/hasaneyldrm/exercises-dataset/main/videos/0873-RqOtqD7.gif', TRUE, 'weight_reps'),
  ('ex_cable_seated_crunch', 'Na kladce v sedě Zkracovačky na břicho', 'Břicho', '{"obliques"}', 'Sit on a cable machine with your feet flat on the ground and your knees bent. Hold the cable handle with both hands and position it behind your head. Engage your abs and slowly curl your upper body forward, bringing your chest towards your knees.', 'https://raw.githubusercontent.com/hasaneyldrm/exercises-dataset/main/videos/0212-8xUv4J7.gif', TRUE, 'weight_reps'),
  ('ex_cable_seated_twist', 'Na kladce v sedě twist', 'Břicho', '{"obliques"}', 'Sit on a cable machine with your feet flat on the ground and your knees slightly bent. Hold the cable handle with both hands and extend your arms straight in front of you. Keeping your core engaged, slowly rotate your torso to one side, pulling the cable across your body.', 'https://raw.githubusercontent.com/hasaneyldrm/exercises-dataset/main/videos/2399-UEjSrKI.gif', TRUE, 'weight_reps'),
  ('ex_cable_side_bend', 'Na kladce side bend', 'Břicho', '{"obliques"}', 'Stand with your feet shoulder-width apart and grasp the cable handle with one hand. Keep your back straight and your core engaged. Slowly bend sideways at the waist, lowering the cable handle towards your knee.', 'https://raw.githubusercontent.com/hasaneyldrm/exercises-dataset/main/videos/0222-wPypxFY.gif', TRUE, 'weight_reps'),
  ('ex_cable_side_crunch', 'Na kladce side Zkracovačky na břicho', 'Břicho', '{"obliques"}', 'Attach a cable handle to a low pulley and stand sideways to the machine. Grasp the handle with the hand furthest from the machine and place your other hand on your hip. Keep your feet shoulder-width apart and your knees slightly bent.', 'https://raw.githubusercontent.com/hasaneyldrm/exercises-dataset/main/videos/0223-q2ADGqV.gif', TRUE, 'weight_reps'),
  ('ex_cable_standing_crunch', 'Na kladce ve stoje Zkracovačky na břicho', 'Břicho', '{"obliques"}', 'Attach a cable handle to a high pulley and stand facing away from the machine. Hold the handle with both hands and place it behind your head, keeping your elbows bent. Stand with your feet shoulder-width apart and your knees slightly bent.', 'https://raw.githubusercontent.com/hasaneyldrm/exercises-dataset/main/videos/0226-jpgqxiS.gif', TRUE, 'weight_reps'),
  ('ex_cable_standing_crunch_with_rope_attachment', 'Na kladce ve stoje Zkracovačky na břicho (with rope attachment)', 'Břicho', '{"obliques"}', 'Attach a rope to a cable machine at chest height. Stand facing away from the machine with your feet shoulder-width apart. Hold the rope with both hands and bring it behind your head, keeping your elbows bent.', 'https://raw.githubusercontent.com/hasaneyldrm/exercises-dataset/main/videos/0874-XU3ePuv.gif', TRUE, 'weight_reps'),
  ('ex_cable_standing_lift', 'Na kladce ve stoje lift', 'Břicho', '{"obliques","Spodní záda"}', 'Stand facing the cable machine with your feet shoulder-width apart. Hold the cable handle with both hands and position it at waist height. Engage your core and maintain a straight back throughout the exercise.', 'https://raw.githubusercontent.com/hasaneyldrm/exercises-dataset/main/videos/0230-qFpAkpP.gif', TRUE, 'weight_reps'),
  ('ex_cable_tuck_reverse_crunch', 'Na kladce tuck reverse Zkracovačky na břicho', 'Břicho', '{"Ohybače kyčlí"}', 'Attach a cable to a low pulley and lie down on a mat facing up. Hold the cable with both hands and extend your arms straight up above your chest. Bend your knees and lift your legs up, bringing your knees towards your chest.', 'https://raw.githubusercontent.com/hasaneyldrm/exercises-dataset/main/videos/0242-TXtXc84.gif', TRUE, 'weight_reps'),
  ('ex_cable_twist_up_down', 'Na kladce twist (up-down)', 'Břicho', '{"obliques","Spodní záda"}', 'Stand with your feet shoulder-width apart, facing the cable machine. Hold the cable handle with both hands in front of your chest, keeping your arms slightly bent. Engage your core and slowly rotate your torso to one side, keeping your hips and legs stable.', 'https://raw.githubusercontent.com/hasaneyldrm/exercises-dataset/main/videos/0862-fhZQPlV.gif', TRUE, 'weight_reps'),
  ('ex_captains_chair_straight_leg_raise', 'Captains chair straight Zvedání nohou', 'Břicho', '{"Ohybače kyčlí"}', 'Sit on the captain''s chair with your back against the backrest and your forearms resting on the arm pads. Keep your upper body stable and your back straight. Engage your abs and lift your legs up in front of you, keeping them straight.', 'https://raw.githubusercontent.com/hasaneyldrm/exercises-dataset/main/videos/2963-weoDEpH.gif', TRUE, 'reps_only'),
  ('ex_cocoons', 'Cocoons', 'Břicho', '{"Ohybače kyčlí","Spodní záda"}', 'Lie flat on your back with your knees bent and feet flat on the ground. Place your hands behind your head with your elbows pointing outwards. Engaging your abs, slowly lift your upper body off the ground, curling forward until your torso is at a 45-degree angle.', 'https://raw.githubusercontent.com/hasaneyldrm/exercises-dataset/main/videos/0260-SLKj2pX.gif', TRUE, 'reps_only'),
  ('ex_crab_twist_toe_touch', 'Crab twist toe touch', 'Břicho', '{"obliques","Ohybače kyčlí"}', 'Start by sitting on the ground with your knees bent and feet flat on the floor. Place your hands behind you, fingers pointing towards your feet, and lift your hips off the ground. Extend one leg straight out in front of you while simultaneously reaching your opposite hand towards your toes.', 'https://raw.githubusercontent.com/hasaneyldrm/exercises-dataset/main/videos/1468-xgsGFVM.gif', TRUE, 'reps_only'),
  ('ex_cross_body_crunch', 'Cross body Zkracovačky na břicho', 'Břicho', '{"obliques"}', 'Lie flat on your back with your knees bent and feet flat on the ground. Place your hands behind your head with your elbows pointing outwards. Engaging your abs, lift your upper body off the ground and twist to bring your right elbow towards your left knee.', 'https://raw.githubusercontent.com/hasaneyldrm/exercises-dataset/main/videos/0262-rbu5UUb.gif', TRUE, 'reps_only'),
  ('ex_crunch_hands_overhead', 'Zkracovačky na břicho (hands overhead)', 'Břicho', '{"Ohybače kyčlí"}', 'Lie flat on your back with your knees bent and feet flat on the ground. Extend your arms straight above your head. Engaging your abs, lift your upper body off the ground, curling forward towards your knees.', 'https://raw.githubusercontent.com/hasaneyldrm/exercises-dataset/main/videos/0267-kjJ3VoQ.gif', TRUE, 'reps_only'),
  ('ex_curl_up', 'Bicepsový zdvih-up', 'Břicho', '{"Ohybače kyčlí"}', 'Lie flat on your back with your knees bent and feet flat on the ground. Place your hands behind your head with your elbows pointing outwards. Engaging your abs, slowly lift your upper body off the ground, curling forward until your torso is at a 45-degree angle.', 'https://raw.githubusercontent.com/hasaneyldrm/exercises-dataset/main/videos/3016-g2oKspu.gif', TRUE, 'reps_only'),
  ('ex_dead_bug', 'Dead bug', 'Břicho', '{"Ohybače kyčlí","Spodní záda"}', 'Lie flat on your back with your arms extended towards the ceiling. Bend your knees and lift your legs off the ground, creating a 90-degree angle at your hips and knees. Engage your core and lower back to press your lower back into the ground.', 'https://raw.githubusercontent.com/hasaneyldrm/exercises-dataset/main/videos/0276-iny3m5y.gif', TRUE, 'reps_only'),
  ('ex_decline_crunch', 'Hlavou dolů Zkracovačky na břicho', 'Břicho', '{"Ohybače kyčlí"}', 'Lie on a decline bench with your feet secured and your knees bent at a 90-degree angle. Place your hands behind your head or across your chest. Engage your abs and lift your upper body towards your knees, curling your torso.', 'https://raw.githubusercontent.com/hasaneyldrm/exercises-dataset/main/videos/0277-9Ap7miY.gif', TRUE, 'reps_only'),
  ('ex_astride_jumps_male', 'Astride jumps (male)', 'Kardio', '{"Kvadricepsy","Hamstringy","Lýtka"}', 'Stand with your feet shoulder-width apart. Bend your knees and lower your body into a squat position. Jump explosively upwards, extending your legs and arms.', 'https://raw.githubusercontent.com/hasaneyldrm/exercises-dataset/main/videos/3220-f9lVSSI.gif', TRUE, 'duration'),
  ('ex_back_and_forth_step', 'Back a forth step', 'Kardio', '{"Kvadricepsy","Hamstringy","Hýždě"}', 'Stand with your feet shoulder-width apart. Step forward with your right foot, bending your knee and lowering your body into a lunge position. Push off with your right foot and step back to the starting position.', 'https://raw.githubusercontent.com/hasaneyldrm/exercises-dataset/main/videos/3672-fNGumX0.gif', TRUE, 'duration'),
  ('ex_bear_crawl', 'Bear crawl', 'Kardio', '{"Střed těla","Ramena","Triceps"}', 'Start on all fours with your hands directly under your shoulders and your knees directly under your hips. Lift your knees slightly off the ground, keeping your back flat and your core engaged. Move your right hand and left foot forward simultaneously, followed by your left hand and right foot.', 'https://raw.githubusercontent.com/hasaneyldrm/exercises-dataset/main/videos/3360-0Yz8WdV.gif', TRUE, 'duration'),
  ('ex_burpee', 'Angličáky (Burpees)', 'Kardio', '{"Kvadricepsy","Hamstringy","Lýtka"}', 'Start in a standing position with your feet shoulder-width apart. Lower your body into a squat position by bending your knees and placing your hands on the floor in front of you. Kick your feet back into a push-up position.', 'https://raw.githubusercontent.com/hasaneyldrm/exercises-dataset/main/videos/1160-dK9394r.gif', TRUE, 'duration'),
  ('ex_cycle_cross_trainer', 'Cycle cross trainer', 'Kardio', '{"Kvadricepsy","Hamstringy","Hýždě"}', 'Adjust the seat height and position yourself on the cycle cross trainer. Place your feet on the pedals and grip the handlebars. Start pedaling in a smooth and controlled motion.', 'https://raw.githubusercontent.com/hasaneyldrm/exercises-dataset/main/videos/2331-XSCHmiI.gif', TRUE, 'duration'),
  ('ex_dumbbell_burpee', 'Angličáky (Burpees)', 'Kardio', '{"Kvadricepsy","Hamstringy","Lýtka"}', 'Start in a standing position with your feet shoulder-width apart and a dumbbell in each hand. Lower your body into a squat position, placing the dumbbells on the ground in front of you. Kick your feet back into a push-up position, keeping your body in a straight line.', 'https://raw.githubusercontent.com/hasaneyldrm/exercises-dataset/main/videos/1201-0JtKWum.gif', TRUE, 'duration'),
  ('ex_half_knee_bends_male', 'Half knee bends (male)', 'Kardio', '{"Kvadricepsy","Hamstringy","Hýždě"}', 'Stand with your feet shoulder-width apart. Bend your knees and lower your body down as if you were sitting back into a chair. Keep your chest up and your weight in your heels.', 'https://raw.githubusercontent.com/hasaneyldrm/exercises-dataset/main/videos/3221-ia6kIIl.gif', TRUE, 'duration'),
  ('ex_high_knee_against_wall', 'High knee against wall', 'Kardio', '{"Kvadricepsy","Hamstringy","Hýždě"}', 'Stand facing a wall with your feet hip-width apart. Place your hands on the wall for support. Engage your core and lift your right knee up towards your chest, while keeping your left foot on the ground.', 'https://raw.githubusercontent.com/hasaneyldrm/exercises-dataset/main/videos/3636-ealLwvX.gif', TRUE, 'duration'),
  ('ex_jack_burpee', 'Angličáky (Burpees)', 'Kardio', '{"Kvadricepsy","Hamstringy","Lýtka"}', 'Start in a standing position with your feet shoulder-width apart. Lower your body into a squat position, placing your hands on the ground in front of you. Kick your feet back, landing in a push-up position.', 'https://raw.githubusercontent.com/hasaneyldrm/exercises-dataset/main/videos/0501-mr7pkqP.gif', TRUE, 'duration'),
  ('ex_jack_jump_male', 'Jack jump (male)', 'Kardio', '{"Kvadricepsy","Lýtka"}', 'Stand with your feet together and your arms by your sides. Jump up, spreading your feet apart and raising your arms above your head. As you land, quickly jump back to the starting position.', 'https://raw.githubusercontent.com/hasaneyldrm/exercises-dataset/main/videos/3224-1g5bPpA.gif', TRUE, 'duration'),
  ('ex_push_to_run', 'Push to run', 'Kardio', '{"Kvadricepsy","Hamstringy","Lýtka"}', 'Start in a push-up position with your hands shoulder-width apart and your body in a straight line. Lower your chest towards the ground by bending your elbows, keeping your body straight. Push through your hands to extend your arms and return to the starting position.', 'https://raw.githubusercontent.com/hasaneyldrm/exercises-dataset/main/videos/3638-PrQbjvB.gif', TRUE, 'duration'),
  ('ex_run', 'Run', 'Kardio', '{"Kvadricepsy","Hamstringy","Lýtka"}', 'Start by standing upright with your feet hip-width apart. Engage your core and keep your upper body relaxed. Begin jogging in place, lifting your knees up towards your chest and landing softly on the balls of your feet.', 'https://raw.githubusercontent.com/hasaneyldrm/exercises-dataset/main/videos/0685-oLrKqDH.gif', TRUE, 'duration'),
  ('ex_run_equipment', 'Run (equipment)', 'Kardio', '{"Kvadricepsy","Hamstringy","Lýtka"}', 'Start by standing upright with your feet hip-width apart. Engage your core and keep your upper body relaxed. Begin jogging in place, lifting your knees up towards your chest and landing softly on the balls of your feet.', 'https://raw.githubusercontent.com/hasaneyldrm/exercises-dataset/main/videos/0684-y5p0H8a.gif', TRUE, 'duration'),
  ('ex_scissor_jumps_male', 'Scissor jumps (male)', 'Kardio', '{"Kvadricepsy","Hamstringy","Lýtka"}', 'Stand with your feet shoulder-width apart. Jump off the ground and simultaneously cross your right leg in front of your left leg. As you land, quickly switch legs, crossing your left leg in front of your right leg.', 'https://raw.githubusercontent.com/hasaneyldrm/exercises-dataset/main/videos/3219-Eh2v5Iu.gif', TRUE, 'duration'),
  ('ex_semi_squat_jump_male', 'Semi Dřep jump (male)', 'Kardio', '{"Kvadricepsy","Hamstringy","Lýtka"}', 'Stand with your feet shoulder-width apart. Bend your knees and lower your body into a squat position. Jump explosively, extending your hips and knees while swinging your arms for momentum.', 'https://raw.githubusercontent.com/hasaneyldrm/exercises-dataset/main/videos/3222-6FMU51h.gif', TRUE, 'duration'),
  ('ex_short_stride_run', 'Short stride run', 'Kardio', '{"Kvadricepsy","Hamstringy","Lýtka"}', 'Find an open space or a treadmill to perform the exercise. Stand tall with your feet hip-width apart. Start jogging in place, lifting your knees high and pumping your arms.', 'https://raw.githubusercontent.com/hasaneyldrm/exercises-dataset/main/videos/3656-CcWEoWV.gif', TRUE, 'duration'),
  ('ex_skater_hops', 'Skater hops', 'Kardio', '{"Kvadricepsy","Hamstringy","Hýždě"}', 'Stand with your feet shoulder-width apart. Bend your knees slightly and jump to the right, landing on your right foot. As you land, swing your left leg behind your right leg and tap the ground with your left toes.', 'https://raw.githubusercontent.com/hasaneyldrm/exercises-dataset/main/videos/3361-zfNHMN9.gif', TRUE, 'duration'),
  ('ex_ski_step', 'Ski step', 'Kardio', '{"Kvadricepsy","Hamstringy","Hýždě"}', 'Stand with your feet shoulder-width apart. Bend your knees slightly and keep your back straight. Jump to the right, landing on your right foot while swinging your left leg behind your right leg.', 'https://raw.githubusercontent.com/hasaneyldrm/exercises-dataset/main/videos/3671-5MRH8H2.gif', TRUE, 'duration'),
  ('ex_star_jump_male', 'Star jump (male)', 'Kardio', '{"Kvadricepsy","Hamstringy","Lýtka"}', 'Stand with your feet shoulder-width apart and your arms by your sides. Bend your knees slightly and jump up explosively. As you jump, spread your legs and extend your arms out to the sides, forming a star shape with your body.', 'https://raw.githubusercontent.com/hasaneyldrm/exercises-dataset/main/videos/3223-HtfCpfi.gif', TRUE, 'duration'),
  ('ex_swing_360', 'Swing 360', 'Kardio', '{"Ramena","Střed těla"}', 'Stand with your feet shoulder-width apart and knees slightly bent. Hold your arms straight out in front of you, parallel to the ground. Engage your core and swing your arms in a circular motion, rotating your torso as you do so.', 'https://raw.githubusercontent.com/hasaneyldrm/exercises-dataset/main/videos/3318-tnaj0mT.gif', TRUE, 'duration')
